/* Original teaching materials. CEFR labels indicate intended practice, not certified attainment. */
(() => {
  'use strict';
  const sources = {
    cefr: {label: 'Council of Europe · CEFR descriptors', url: 'https://www.coe.int/en/web/common-european-framework-reference-languages/cefr-descriptors'},
    cautious: {label: 'University of Manchester · Being cautious', url: 'https://www.phrasebank.manchester.ac.uk/using-cautious-language/'},
    synthesis: {label: 'Purdue OWL · Synthesizing sources', url: 'https://owl.purdue.edu/owl/research_and_citation/conducting_research/research_overview/synthesizing_sources.html'},
    paraphrase: {label: 'Purdue OWL · Paraphrasing', url: 'https://owl.purdue.edu/owl/research_and_citation/using_research/quoting_paraphrasing_and_summarizing/paraphrasing.html'},
    pronunciation: {label: 'Cambridge Dictionary · Pronunciation', url: 'https://dictionary.cambridge.org/us/pronunciation/'},
    stress: {label: 'British Council · Word stress', url: 'https://www.teachingenglish.org.uk/professional-development/teachers/teaching-knowledge-database/t-w/word-stress'}
  };
  const vocab = (word, meaning, example) => ({word, meaning, example});
  const point = (title, text) => ({title, text});
  const question = (skill, prompt, options, answer, explanation) => ({skill, prompt, options, answer, explanation});
  const lesson = (item) => ({...item, questions: item.questions.map((q, i) => ({id: `${item.id}-q${i + 1}`, ...q}))});
  const assessment = (level, item) => ({...item, questions: item.questions.map((q, i) => ({id: `${level}-check-q${i + 1}`, ...q}))});
  const b1 = {
    id: 'b1', label: 'B1', title: '把英语用于独立学习与生活',
    description: '从连贯叙述、说明理由和解决沟通问题，走向短文概括与小型项目。阅读和听力材料分开，先听后看文本。',
    canDo: ['连贯讲述经历，说明原因与结果', '理解清晰短讲与实用说明的主旨和重要细节', '写出有理由的短文，并在不理解时澄清'],
    sources: [sources.cefr, sources.stress, sources.pronunciation],
    foundations: [{course: 'word-parts', lessonId: 'inflection-and-derivation', label: '词形变化与新词'}, {course: 'phonics', lessonId: 'syllables-stress-schwa', label: '音节、重音与弱读'}],
    lessons: [
      lesson({id: 'b1-experience', title: '讲清经历：背景、变化与结果', skill: '叙述 · 时态', minutes: 30,
        goals: ['区分故事背景和先后发生的事件', '用具体事件支持感受和反思'],
        explanation: [point('给故事一条时间线', '用过去进行时提供背景，用一般过去时推进事件。When I arrived, people were arranging chairs. 不等于两个动作都已结束。'), point('把反思接到事实', '先写发生了什么，再说明它如何改变你的做法。because 说明原因，although 引入与结果形成反差的情况。')],
        vocabulary: [vocab('arrange', '安排；摆放', 'We arranged the chairs in a circle.'), vocab('hesitate', '犹豫', 'I hesitated before asking for help.'), vocab('eventually', '最终；经过一段过程后', 'Eventually, we found the right room.')],
        reading: {title: 'The wrong room', text: `When I arrived at the community centre, several people were moving tables. I thought they were preparing for the photography course, so I offered to help. After twenty minutes, the organiser thanked me and handed me a cooking apron. I had joined the wrong group. At first I felt embarrassed, but the organiser showed me where the photography class was meeting. I arrived late and missed the introduction. Instead of sitting silently, I explained the mistake and asked a classmate what I needed. She shared her notes with me. I still check room numbers carefully now, but that evening also taught me something useful: asking a simple question can solve a problem faster than pretending to understand.`, support: '找出原计划、误会、补救三个节点。注意最后一句是在反思，不是新的事件。'},
        listening: {title: 'A first volunteer shift', text: `I used to think volunteering meant knowing exactly what to do. On my first shift at a book sale, a visitor asked where the history books were. I guessed and sent him upstairs. They were actually near the entrance. My supervisor did not ask me to memorise every shelf. She showed me the map and said I could check it with the visitor. Later, when somebody asked about travel books, I used the map instead of guessing. We found them together. I felt more confident because I had a way to find an answer, even when I did not know it immediately.`, focus: '听出第一次和第二次回答问题时，讲述者的做法怎样变化。'},
        questions: [question('reading', 'What was happening when the writer arrived?', ['The photography lesson was ending.', 'People were moving tables.', 'A classmate was sharing notes.'], 1, 'were moving 描述到达时正在发生的背景。'), question('reading', 'Which lesson does the writer draw from the experience?', ['It is better to hide a mistake.', 'Helping people always causes delays.', 'Asking for clarification is useful.'], 2, '最后一句把提问与解决问题联系起来。'), question('listening', 'Why was the first visitor sent upstairs?', ['The volunteer guessed the location.', 'The map was out of date.', 'The supervisor gave that instruction.'], 0, '讲述者明确说 I guessed；不是地图或主管出错。'), question('listening', 'What increased the speaker’s confidence?', ['Memorising every book title.', 'Learning how to check an answer.', 'Avoiding visitors with questions.'], 1, '信心来自有方法查找，而非知道所有答案。')],
        production: {writing: '写 120–150 词：一次误会、你采取的补救和以后会怎样做。', speaking: '用 60–90 秒讲述同一事件；加入一处背景描述和一句反思。', model: '参考片段：I was waiting outside the lab when I noticed that the door number was different. I checked the message and realised the meeting had moved. Although I arrived late, I explained the problem and joined the discussion. Next time, I will check the latest message before leaving home.', rubric: ['事件有清楚的时间顺序，背景与主要动作可区分', '写明一个补救动作及它的结果', '反思有事实支持，口述时关键事件容易听清']},
        review: {prompt: '不看课文，用四句英语复述“去错教室”的原因、结果和补救；再把一个句子改成背景＋事件结构。', answer: '应包含误认准备活动、拿到围裙才发现、迟到后向同学求助。例：People were moving tables when the writer arrived.'}}),
      lesson({id: 'b1-instructions', title: '读懂条件，说明操作步骤', skill: '说明 · 条件句', minutes: 30,
        goals: ['从说明中区分必做事项与条件事项', '在沟通中确认时间和责任'],
        explanation: [point('条件不是确定发生的事', 'If the room is locked, call reception. 只有门锁着才打电话。unless 表示“除非”，读到它先写出不成立时会怎样。'), point('给步骤加检查点', '用 first、before、once、finally 表示顺序；每一步说明谁做、做什么、如何确认完成。')],
        vocabulary: [vocab('reserve', '预约；保留', 'Reserve a study room online.'), vocab('confirm', '确认', 'Please confirm the start time.'), vocab('equipment', '设备；通常不可数', 'The equipment is ready to use.')],
        reading: {title: 'Borrowing a recording kit', text: `Students can borrow a recording kit for a class project. First, reserve a collection time online. Before you arrive, complete the short equipment lesson and bring your student card. Staff will check both your booking and your card. You may keep the kit for two days unless another group has booked it for the following day; the return time will appear in your confirmation email. Test the microphone before leaving the desk. If a cable is missing, tell a member of staff immediately. Do not buy a replacement yourself. When you return the kit, wait while staff check the contents. Leaving it outside the office does not count as returning it.`, support: '用两栏记录“所有人必须做”与“某条件下才做”。确认邮件决定具体归还时间。'},
        listening: {title: 'A change to the collection plan', text: `Hi, this is Sam from the media desk. Your recording kit is ready, but we have changed your collection point. Please come to the library desk, not the office in the arts building. Your booking is still for three o’clock. If you cannot arrive by half past three, call us, because the librarian will take the kit back to our office. You do not need to repeat the online equipment lesson. We can see that you completed it yesterday. One more thing: the kit includes a microphone and headphones, but you need to bring your own laptop to save the recording.`, focus: '记录变了什么、没变什么，以及迟到时应做什么。'},
        questions: [question('reading', 'What determines the exact return time?', ['The length of the student’s project.', 'The confirmation email.', 'The price of a replacement cable.'], 1, '两天有例外，最终时间写在确认邮件中。'), question('reading', 'Which action completes the return?', ['Leaving the kit by the closed office.', 'Sending a photograph of the kit.', 'Waiting for staff to check its contents.'], 2, '最后两句明确区分实际归还与放在门外。'), question('listening', 'What changed in Sam’s message?', ['The collection place.', 'The booking time.', 'The required online lesson.'], 0, '改为 library desk，三点和已完成的线上课未变。'), question('listening', 'Why should the borrower bring a laptop?', ['To book another kit.', 'To save the recording.', 'To complete the equipment lesson again.'], 1, '麦克风和耳机已包含；电脑用于保存录音。')],
        production: {writing: '给同伴写 100–140 词领取说明，整合阅读要求与语音变更；明确迟到处理。', speaking: '模拟电话确认：复述地点和时间，再问一个尚未回答的问题。', model: 'We will collect the kit from the library desk at three. I have completed the equipment lesson, and I will bring my student card and laptop. If we are likely to arrive after three thirty, we should call first. Could you confirm where we should return the kit?', rubric: ['准确整合新地点和未改变的时间', '条件句没有把可能发生的情况写成必然事件', '至少一次确认信息，并提出材料未解决的问题']},
        review: {prompt: '关掉材料，写出领取前两件必做事项和一条条件规则；口头解释 why leaving a kit outside is insufficient。', answer: '必做事项可选预约、完成设备课、带学生证；条件规则如缺少线缆须立即告知。归还要等工作人员核对物品。'}}),
      lesson({id: 'b1-compare-options', title: '比较选择，不只说更好', skill: '比较 · 决策', minutes: 30,
        goals: ['用共同标准比较两个方案', '理解让步后仍成立的理由'],
        explanation: [point('先确定标准', '比较交通、费用或可用时间，不要在两个方案间更换标准。A is cheaper than B, but B is closer. 是两个可检验的比较。'), point('让步连接选择', 'Although A is cheaper, I prefer B because... 承认对方优点后解释自己的优先项，而不是否认该优点。')],
        vocabulary: [vocab('affordable', '负担得起的', 'The fee is affordable for our group.'), vocab('convenient', '方便的', 'The evening session is convenient for me.'), vocab('priority', '优先考虑的事', 'Reliable transport is my priority.')],
        reading: {title: 'Choosing a language group', text: `Mina wants to join a weekly conversation group. The community centre charges less than the university club, and its groups are smaller. However, its Thursday meeting ends after the last direct bus to Mina’s neighbourhood. She could take two buses, but the trip would be long. The university club meets on Tuesday, when Mina already has classes on campus. Its meetings are shorter and sometimes noisy because they take place in a shared room. Mina chooses the university club for the first month. She does not think it is better in every way. She wants a group that she can attend regularly, and she plans to reconsider her choice if the noise makes conversation difficult.`, support: '把费用、交通、环境列成表。解释选择时区分“最优先的标准”与“所有方面都最好”。'},
        listening: {title: 'Two study spaces', text: `We could work at my flat or in the public library. My flat has a large table, and we can talk freely there. The problem is that my brother will be practising the drums this Saturday. The library is quieter, but its group rooms must be booked. I checked this morning, and there is one available from ten until twelve. We will need to finish the planning in two hours. Since we mainly need to agree on our presentation outline, I think that is enough. Let’s book the room and do the individual writing afterwards.`, focus: '听出推荐方案与限制，并判断为什么限制在这次任务中可以接受。'},
        questions: [question('reading', 'What matters most in Mina’s initial choice?', ['Having the smallest group.', 'Paying the lowest fee.', 'Being able to attend regularly.'], 2, '交通和课表使稳定参加成为首要标准。'), question('reading', 'Which statement reflects Mina’s attitude?', ['Her choice is practical and may change.', 'The university club has no disadvantages.', 'Smaller groups are never helpful.'], 0, '她承认噪声问题，并计划必要时重新考虑。'), question('listening', 'Why does the speaker accept the library’s time limit?', ['They have already written everything.', 'Two hours should be enough for planning.', 'The library will extend the booking.'], 1, '当前任务是商定提纲，不是完成全部写作。'), question('listening', 'What will the group do after using the room?', ['Visit the speaker’s brother.', 'Book all future Saturdays.', 'Write their individual parts.'], 2, '结尾明确将个人写作放在讨论之后。')],
        production: {writing: '比较两个真实学习地点，写 130–160 词建议，使用三个相同标准并说明首选。', speaking: '用 90 秒向同伴推荐其中一个，同时承认它的一项限制。', model: 'The café is cheaper and allows longer visits, whereas the library offers a quieter room. Although the booking lasts only two hours, that is enough to plan our project. I therefore recommend the library for the discussion and the café for individual work afterwards.', rubric: ['两方案按相同标准比较，事实与偏好分开', '建议有明确优先项并承认一项缺点', '用比较或让步结构连接理由，而非只列形容词']},
        review: {prompt: '从记忆解释 Mina 为什么没有选最便宜的地方；再用 although 写一个你自己的决定。', answer: '社区中心结束太晚，回家不便；她优先稳定出席。例：Although the café is closer, I prefer the library because I need a quiet room.'}}),
      lesson({id: 'b1-explain-repair', title: '解释陌生事物，修复误解', skill: '释义 · 互动', minutes: 30,
        goals: ['用关系从句和例子解释陌生词', '通过复述确认双方理解一致'],
        explanation: [point('忘记单词也能解释', '用 a tool that...、a place where...、a person who... 描述用途或特征。先说类别，再给区分它的细节。'), point('核对，不机械重复', 'Do you mean...? 后给出你的理解；So I should... 用动作检验理解。请对方举例通常比只说 I do not understand 更具体。')],
        vocabulary: [vocab('clarify', '澄清', 'Could you clarify what “draft” means here?'), vocab('attach', '附上；连接', 'Attach the file to your message.'), vocab('version', '版本', 'This is the version with your comments.')],
        reading: {title: 'What counts as a draft?', text: `Leo’s tutor asked him to send a draft before Friday. Leo thought a draft had to be nearly perfect, so he spent several evenings correcting sentences and still had not finished the main section. In class, another student described a draft as a working version that other people can respond to. Leo asked his tutor whether an outline and two unfinished paragraphs would be useful. She said they would: she wanted to discuss his question and structure before he wrote the whole assignment. Leo sent the work with a note explaining which parts were incomplete. The tutor’s comments helped him change the order of his ideas before he spent more time polishing the language.`, support: '关注 draft 的用途，而非“完成百分比”。比较 Leo 最初的理解与导师的期待。'},
        listening: {title: 'Checking the upload request', text: `Please attach your slides to the group page before tonight. By slides, I mean the file you will show during the presentation, not the notes you will read aloud. You can keep your speaking notes in a separate document. Someone asked whether the pictures need to be final. No, simple boxes are fine if the captions explain what you plan to add. We need to check the order of the talk first. If your file is too large to upload, share a link that other group members can open. Please test the link with one classmate before you leave it on the page.`, focus: '把 slides、notes、pictures 的要求分开，听出上传困难时的替代办法。'},
        questions: [question('reading', 'Why did Leo delay sending his work?', ['He believed it needed to be nearly perfect.', 'His tutor refused unfinished paragraphs.', 'He had not received a deadline.'], 0, '误解 draft 的要求导致过度打磨。'), question('reading', 'What was the tutor’s main purpose at this stage?', ['Correcting every spelling error.', 'Discussing the question and structure.', 'Choosing pictures for a presentation.'], 1, '导师要尽早反馈论题和结构。'), question('listening', 'Which file does the speaker want?', ['Only the private speaking notes.', 'Only the final pictures.', 'The slides shown during the talk.'], 2, '讲述者明确区分展示文件与口头提示笔记。'), question('listening', 'What should students do before posting a shared link?', ['Check that a classmate can open it.', 'Remove every caption.', 'Print the file at the library.'], 0, 'test the link with one classmate 是链接可用性的检查。')],
        production: {writing: '写 100–140 词邮件：复述你对 draft 的理解，说明现有材料，并提出一个具体确认问题。', speaking: '不用说出目标词，描述三件学习用品；再模拟一次“Do you mean...?” 澄清。', model: 'To check my understanding, you would like a working version so that we can discuss the structure. I have an outline and two paragraphs, but the final section is incomplete. Would you prefer me to attach these now or add a short explanation of the missing section first?', rubric: ['说明对象类别、用途和一个区分特征', '邮件包含具体的复述和可回答的问题', '没有把未完成的工作描述为完成版']},
        review: {prompt: '不看词汇，用英语解释 draft 和 speaking notes 的不同用途；给出两种澄清句式。', answer: 'Draft 是可供反馈的工作版本；speaking notes 帮助口述。例：Do you mean the file we will show? Could you give an example?' }}),
      lesson({id: 'b1-opinion-evidence', title: '提出观点，也承认范围', skill: '观点 · 理由', minutes: 35,
        goals: ['区分观点、例子与一般结论', '写出有理由和限定的意见段'],
        explanation: [point('例子支持观点，但范围有限', 'My class worked well online 描述一个班；不能直接推出 All students learn better online。保留时间、对象与情境。'), point('观点段的基本次序', '先说明立场，再给理由与例子，最后回应一个合理顾虑。可以保留条件：This works well when...。')],
        vocabulary: [vocab('flexible', '灵活的', 'A flexible timetable helps me attend.'), vocab('distraction', '使人分心的事物', 'Phone messages are a distraction.'), vocab('in my experience', '按我的经历；限定经验范围', 'In my experience, a short plan helps.')],
        reading: {title: 'Should every club meeting be online?', text: `Our student club is considering online meetings. I support keeping some meetings online because members who live far away can join more easily. Last month, I attended from home while waiting for a repair worker. However, this personal example does not tell us what every member needs. Some people have quiet rooms and reliable internet; others share a crowded flat. Face-to-face meetings also make it easier to notice when someone wants to speak. I suggest alternating between online and campus meetings for one month, then asking members what helped them participate. We should ask people who missed meetings as well as those who attended. Otherwise, we might hear only from members whose needs are already being met.`, support: '标出作者支持的实际方案。留意末句指出问谁会影响获得什么信息。'},
        listening: {title: 'A response from another member', text: `I agree that online meetings can help, but changing the location will not solve everything. I missed two campus meetings because they were held during my work shift. An online meeting at the same time would still be difficult for me. Could we try a different time as well? We should not change the time every week, though, because people need to plan ahead. Perhaps we could offer two possible times in a short message and ask everyone to choose. I would also like the main decisions written down so that members who cannot attend can still contribute afterwards.`, focus: '听出说话者新增的原因，以及对解决办法提出的限制。'},
        questions: [question('reading', 'What does the writer actually recommend?', ['Holding every meeting online permanently.', 'Trying a mixed arrangement and gathering feedback.', 'Allowing only regular attendees to vote.'], 1, '建议为一个月试行并反馈，不是永久全线上。'), question('reading', 'Why ask members who missed meetings?', ['Their views may reveal unmet needs.', 'They must apologise before returning.', 'They already prefer online meetings.'], 0, '缺席者可能正是现有安排无法满足的人。'), question('listening', 'What prevented this member from attending?', ['A broken internet connection.', 'A lack of interest in the club.', 'A conflict with working hours.'], 2, '工作时段冲突不因会议搬到网上自动解决。'), question('listening', 'Which proposal does the member reject?', ['Writing down main decisions.', 'Changing the time every week.', 'Asking members to choose between two times.'], 1, '频繁改变时间不利于提前安排。')],
        production: {writing: '写 150–180 词建议，结合两份材料提出一个试行安排；不要声称已经证明最有效。', speaking: '用 90 秒提出方案，然后用一句话回应“并非人人能参加”的反对意见。', model: 'A trial could combine a predictable timetable with different meeting formats. The first writer highlights travel difficulties, while the speaker identifies work schedules as another barrier. I suggest asking all members about two regular times before choosing one. We can then review attendance and written feedback after a month.', rubric: ['意见有理由和材料中的具体例子', '至少保留一个限制，未把个人经历普遍化', '回应对方顾虑，并提出可执行的下一步']},
        review: {prompt: '写一句不合理的 All students... 概括，再改成有对象、条件或经验范围的观点；回忆两种参会障碍。', answer: '可改为 In my experience, online meetings help when travel is difficult. 障碍包括交通、工作时间、居住环境与网络。'}}),
      lesson({id: 'b1-word-families', title: '用词族读懂通知与短文', skill: '构词 · 词性', minutes: 30,
        goals: ['结合句法位置判断词族成员的用途', '不把熟悉词缀当成整词含义的保证'],
        explanation: [point('同时记形式、搭配和词性', 'participate in 是动词搭配；participation in 是名词搭配。able → ability 与 available → availability 是不同词族，应放回句子学习，不能只背词尾或混为同一词族。'), point('构词提供假设', 'reusable 可由 reuse 和 -able 理解；但不是所有相似字母都能机械拆分。遇到语义不通时查整词和例句。')],
        vocabulary: [vocab('participation', '参与；名词', 'Participation in the workshop is free.'), vocab('reusable', '可重复使用的', 'Bring a reusable container.'), vocab('availability', '可用性；有空的情况', 'Tell us your availability for next week.')],
        reading: {title: 'A repair workshop notice', text: `The campus repair group welcomes participation from beginners. You do not need to be an experienced repairer, but you must follow the safety instructions given by the workshop leader. Participants may bring small non-electrical items, such as bags with broken straps. The group will provide reusable tools and some basic materials. We cannot promise that every item will be repairable, so please describe the problem when you register. Registration helps us choose suitable materials; it does not guarantee a successful repair. If you would like to volunteer, tell us your availability for the next three Saturdays. You can participate in one session without joining the organising team.`, support: '找出 participate、participant、participation 的词性与对象；注意 registration 不等于成功保证。'},
        listening: {title: 'The organiser explains the form', text: `Several people have asked about the registration form. The box marked “availability” is for the times when you can help, not a list of tools that are available in your home. If you want to bring an item for repair, use the next box to describe it. A photograph is useful, but it is not required. Please avoid writing only “broken bag”. Tell us whether the strap, zip, or fabric needs attention. This information allows us to prepare suitable materials. If we cannot help with a particular item, we will contact you before the session rather than ask you to carry it to campus unnecessarily.`, focus: '听出 availability 在此表格中的具体含义，以及更详细描述问题的原因。'},
        questions: [question('reading', 'What does registration guarantee?', ['That every item can be repaired.', 'That a beginner becomes an organiser.', 'Neither of these outcomes.'], 2, '登记是准备材料的依据，不保证修复或加入组织团队。'), question('reading', 'Which sentence correctly uses the word family?', ['I can participate in one session.', 'I can participation in one session.', 'I am participate of one session.'], 0, '情态动词后用原形 participate，搭配 in。'), question('listening', 'What belongs in the availability box?', ['Photographs of tools.', 'Times when the person can help.', 'The price of a broken bag.'], 1, '这里 availability 指志愿者有空的时段。'), question('listening', 'Why should the problem description be specific?', ['To prove the item is expensive.', 'To replace the need to register.', 'To help the group prepare or advise in advance.'], 2, '详细信息帮助准备材料，或提前说明无法处理。')],
        production: {writing: '写 120–150 词报名邮件，说明物品问题和可用时间；使用 participate/participation 中至少两个词族形式。', speaking: '用 60 秒说明一件物品能否再次使用；不会的单词用用途或部位描述。', model: '参考片段：I would like to participate in the workshop on Saturday. My participation will depend on whether a suitable place is available. My bag has a loose strap, but the fabric is still strong. Could you let me know whether this type of repair is possible? My availability as a volunteer is limited to the morning. I understand that registration does not guarantee a successful repair.', rubric: ['词族形式适合句法位置，搭配可理解', '描述具体部位与需求，而非只有 broken', '清楚区分可以保证的安排与尚待确认的结果']},
        review: {prompt: '不看材料写 participate、participation、participant 各一个句子，并解释 registration 与 successful repair 的关系。', answer: '例：I participate in workshops. Participation is free. Each participant brings an item. 登记有助准备，但不能确保每件物品修好。'}}),
      lesson({id: 'b1-listening-focus', title: '听重点与纠正，不追逐每个音', skill: '听力 · 重音', minutes: 30,
        goals: ['识别 but、actually 等转折与纠正信号', '用语块和对比重音传递明确含义'],
        explanation: [point('重音服务于信息', '“Friday, not Thursday” 将对比放在日期上。自然语流中的功能词可能弱读，但不是所有非重读音都变成 /ə/。优先找改变意思的词。'), point('分清文本和声音证据', '听力先抓改动、原因和行动。页面朗读是设备合成语音，可能不能稳定呈现对比重音；请自己分语块复述，并用可靠词典核对词重音。')],
        vocabulary: [vocab('actually', '实际上；常引入纠正', 'We will actually meet on Friday.'), vocab('instead', '代替；改为', 'Send a message instead of calling.'), vocab('reschedule', '重新安排时间', 'We need to reschedule the interview.')],
        reading: {title: 'A presentation rehearsal', text: `During a rehearsal, Noor read every word at the same speed. Her partner understood the individual words but missed the main contrast: the team wanted to change the booking system, not the opening hours. Noor divided the sentence into two short groups and paused between them. She also made “booking system” and “opening hours” more prominent. The partner could then explain the proposal accurately. Noor did not try to remove her accent or copy every sound from a recording. She focused on the information that listeners needed. For the next rehearsal, the pair agreed to test understanding by asking a listener to summarise the recommendation before showing the written slides.`, support: '注意问题不是听不懂单词，而是没有听清两项内容的对比。'},
        listening: {title: 'The interview arrangement', text: `A quick correction about our interview: it is on Friday, not Thursday. The time is still ten fifteen. We had planned to meet in the café, but the manager has told us that a delivery will make it noisy. Please come to the small meeting room next to the café instead. You do not need to prepare a new list of questions. Use the one we agreed on yesterday, and bring a printed copy in case the internet is unavailable. If you are delayed, send me a message rather than calling, because I may already be speaking to the guest.`, focus: '第一次只记日期、地点、迟到处理；第二次核对两个“没有改变”的事项。'},
        questions: [question('reading', 'What was the communication problem?', ['The listener did not know any individual words.', 'The contrast between two proposals was unclear.', 'Noor spoke with a completely unfamiliar accent.'], 1, '听者懂单词，但未抓住“改预约系统，不改开放时间”。'), question('reading', 'How will the pair check understanding next time?', ['Ask a listener to summarise before seeing the slides.', 'Count how many words Noor reads.', 'Remove every pause from the talk.'], 0, '用听者复述检验信息是否传达。'), question('listening', 'Which combination is correct?', ['Thursday at ten fifteen in the café.', 'Friday at ten fifty in the meeting room.', 'Friday at ten fifteen in the meeting room.'], 2, '日期改周五、地点改会议室，时间仍 ten fifteen。'), question('listening', 'Why should a delayed student send a message?', ['The guest does not use a phone.', 'The organiser may already be talking to the guest.', 'The question list needs rewriting.'], 1, '不要打断正在进行的访谈。')],
        production: {writing: '写 80–120 词更正通知：改变两项安排，保留一项，说明行动。', speaking: '口述通知，用停顿分组，并让同伴复述改动；自行标出需要强调的词。', model: 'The meeting is on MONDAY, not Tuesday. We will use the LIBRARY room instead of the café. The start time is still nine. Please bring the original notes; you do not need to rewrite them. If the room is locked, wait at reception and send me a message.', rubric: ['两项改动和一项不变的信息准确且明确', '语块之间有合理停顿，关键信息易辨认', '用听者复述或自己的录音回听检查，而非仅追求速度']},
        review: {prompt: '脱离文本说出访谈安排的两个改动和两个不变之处；再录一段含 not...but... 的更正。', answer: '改为周五、咖啡馆旁会议室；时间仍 10:15，问题清单不变。朗读时让纠正信息更突出，是否清楚需回听或请人反馈。'}}),
      lesson({id: 'b1-mini-project', title: '完成一个有反馈的小项目', skill: '综合 · 总结', minutes: 40,
        goals: ['从多条反馈中归纳重点并说明限制', '写出问题、行动、观察和下一步'],
        explanation: [point('报告事实与解释', 'Three members arrived late 是观察；the room was hard to find 是可能解释，须看反馈证据。不要把一次活动写成普遍规律。'), point('短报告也需要边界', '说明参与者和时间，分开已发生的结果与未来计划。短总结应保留读者做决定所需的关键信息。')],
        vocabulary: [vocab('feedback', '反馈；通常不可数', 'We collected feedback after the session.'), vocab('suggestion', '建议', 'One suggestion was to use clearer signs.'), vocab('follow-up', '后续行动', 'Our follow-up is a second practice session.')],
        reading: {title: 'A fictional club project report', text: `This is a fictional teaching example. Our club tried a short welcome session for new students. Twelve people attended. We explained the building map, practised asking for directions, and walked to the main study rooms. Afterwards, eight participants left written feedback. Six said the walk was useful, while two wanted more time to ask questions. Four attendees did not complete the form, so their views are unknown. We cannot conclude that all new students would prefer this activity. For the next session, we plan to shorten the map explanation and add ten minutes for questions. We will keep the walk and ask people who leave early whether another time would suit them better.`, support: '记录 attended 与 left feedback 的不同人数。作者哪些结论有证据，哪些仍未知？'},
        listening: {title: 'Planning the next session', text: `The report gives us a useful starting point, but I want to add something I noticed. Two students arrived halfway through because they had another class. That does not necessarily mean the session started too early for everyone. We should ask them before changing the whole timetable. I like the plan to add question time. Perhaps we can put a simple map online before the session so that we spend less time describing it in the room. We should still bring paper copies for people who cannot open the file. Let’s try these changes once and write down what happens before deciding whether to repeat them.`, focus: '听出讲述者避免了什么推断，以及提出的线上和线下配套措施。'},
        questions: [question('reading', 'Why are the conclusions limited?', ['The walk did not take place.', 'Only eight of twelve attendees gave written feedback.', 'Every new student completed the form.'], 1, '四名参与者未反馈，且这只是一次小活动。'), question('reading', 'Which change is planned?', ['Remove the walk entirely.', 'Make the map explanation longer.', 'Add time for questions.'], 2, '下一次缩短讲图时间，增加十分钟提问。'), question('listening', 'What does the speaker say about the two late students?', ['Ask them before changing the timetable for everyone.', 'They prove that nobody likes the current time.', 'They should not attend future sessions.'], 0, '先确认原因，不由两人直接推及全部参与者。'), question('listening', 'Why keep paper maps?', ['The online file must be deleted.', 'Some people may be unable to open the file.', 'Paper maps provide the feedback results.'], 1, '纸质版本作为访问障碍的替代方式。')],
        production: {writing: '写 160–190 词项目总结：概括已知反馈、指出未知情况并提出两项下一步。', speaking: '做 2 分钟汇报，最后邀请同伴针对一项建议提问。', model: 'In this fictional trial, most respondents valued the walk, but four attendees did not provide written feedback. This limits what we can say about the whole group. We propose keeping the walk, sharing the map in advance and allowing more question time. Before changing the start time, we should ask the students who arrived late about their schedules.', rubric: ['准确保留参与人数与反馈人数的区别', '观察、可能解释和计划没有混写为已证实结果', '下一步回应具体反馈，并包含获取缺失信息的方法']},
        review: {prompt: '不看文本，说明为什么 6 条好评不能写成“所有人都喜欢”；再给出一个收集缺失信息的动作。', answer: '只有 8 人反馈且有 12 人参加，6 条好评只代表部分受访者。可联系未反馈者并用开放问题询问体验。'}})
    ],
    assessment: assessment('b1', {
      reading: {title: 'A fictional community book exchange', text: `This is a fictional teaching example. A neighbourhood group tested a book exchange on two Saturday mornings. Visitors could bring a book or choose one without bringing anything. The organiser, Rosa, wanted the event to feel welcoming, so she did not require registration. On the first morning, many visitors stopped near the entrance because they were unsure whether they had to pay. Before the second morning, the group added a large sign saying that the books were free. Volunteers also explained that taking a book did not create an obligation to volunteer.

At the end of the second morning, Rosa asked six visitors what they thought. They liked the clear signs, but two said the tables were too close together for comfortable browsing. Rosa had not recorded the number of visitors on either day. She therefore could not say whether the new signs had increased attendance. She suggested using wider gaps between tables and counting visitors at the next event. Another volunteer proposed collecting names and email addresses from everyone. Rosa was not convinced that this information was necessary. She preferred an anonymous comment box and a simple visitor count. The group agreed to try her plan before deciding whether to hold the exchange every week.`, support: '新材料；区分活动规则、已观察到的问题与仍无法判断的结果。'},
      listening: {title: 'Volunteer briefing for the next exchange', text: `Thanks for helping at the next book exchange. We will open at ten, but please arrive at nine thirty to move the tables. Last time the gaps were narrow, so this time leave enough space for people to pass without squeezing between chairs. The free-book sign should stay at the entrance. We also need one volunteer to count visitors, but please count each person only when they first arrive. Someone leaving to get a bag and coming back should not be counted twice. We will not ask visitors for their names. If they want to leave feedback, direct them to the comment box near the exit. We may run out of novels before the end. If that happens, explain that visitors are welcome to browse the other books; do not promise that new novels will arrive later. After closing, we will compare our notes and decide what needs changing.`, focus: '记录时间、计数规则和不能承诺的事。'},
      questions: [question('reading', 'Why did Rosa avoid required registration?', ['To make the event welcoming.', 'To sell books more quickly.', 'To recruit every visitor as a volunteer.'], 0, '阅读首段直接给出 welcoming 的目的。'), question('reading', 'What can Rosa conclude from the feedback?', ['Attendance definitely increased.', 'Some respondents found the table spacing uncomfortable.', 'All visitors wanted weekly events.'], 1, '两名反馈者提出通道问题；没有总体人数或全员意见。'), question('reading', 'Why is the effect on attendance unknown?', ['The signs were never displayed.', 'Visitors refused all books.', 'Visitor numbers were not recorded.'], 2, '两天都无人数记录，无法比较出席变化。'), question('reading', 'Which information does Rosa prefer to collect?', ['Anonymous comments and a visitor count.', 'Everyone’s name and home address.', 'Only the number of volunteers.'], 0, '她选择匿名反馈与计数，不要求身份资料。'), question('listening', 'When should volunteers arrive?', ['At ten.', 'At nine thirty.', 'After the event closes.'], 1, '十点开放，志愿者九点半到场布置。'), question('listening', 'How should a visitor who returns with a bag be counted?', ['Once on every entry.', 'Only if they bring a book.', 'Once for their first arrival.'], 2, '明确不要重复计算同一个返回的访客。'), question('listening', 'What should volunteers say if novels run out?', ['Other books are still available to browse.', 'More novels will certainly arrive later.', 'Everyone must leave immediately.'], 0, '可推荐看其他书，不能保证之后补货。'), question('listening', 'What is the purpose of the meeting after closing?', ['To collect visitors’ names.', 'To review observations and possible changes.', 'To require volunteers to buy leftover books.'], 1, '结束后比较记录并决定改进事项。')],
      writing: '写 160–200 词给新志愿者的说明与建议，整合两份材料；包含两项操作、一个尚不确定的结果和收集证据的方法。',
      speaking: '用 2 分钟向未参加的人解释活动如何运作，再回答：“为什么不直接说新标牌提高了出席率？”请写下口述提纲或实录。',
      rubric: ['整合两份材料，规则与时间准确', '连贯说明理由，并保留未知信息的边界', '写作与口述均有明确行动；能用释义处理不熟悉的词'],
      model: '参考片段：The exchange is free, and visitors do not have to bring a book. Volunteers should arrive at nine thirty and leave wider spaces between tables. Although visitors commented positively on the signs, attendance was not counted, so we cannot say that the signs brought more people. A count and anonymous comments will help the group plan the next event.'
    })
  };
  const b2 = {
    id: 'b2', label: 'B2', title: '进入大学学习：分析、讨论与论证',
    description: '处理较长说明与论证，比较证据，解释研究限制，并为不同读者调整表达。任务从理解细节推进到判断推论。',
    canDo: ['比较不同来源的主张、证据和适用范围', '写出有结构的论证并回应合理反对意见', '跟随有路标的讲座，概括重点并提出具体问题'],
    sources: [sources.cefr, sources.cautious, sources.synthesis, sources.paraphrase, sources.pronunciation],
    foundations: [{course: 'word-parts', lessonId: 'abstract-and-person-nouns', label: '抽象名词与学术词族'}, {course: 'phonics', lessonId: 'multisyllable-decoding', label: '长词分块与核对'}],
    lessons: [
      lesson({id: 'b2-source-evaluation', title: '评价来源：谁说的，凭什么', skill: '阅读 · 来源评价', minutes: 40,
        goals: ['区分来源权威与具体主张的证据', '说明一份材料能回答和不能回答的问题'],
        explanation: [point('评价主张与用途的匹配', '校方通知可以确认某服务何时开放，但未必能证明该服务提高学习效果。检查作者、目的、日期、方法和原始证据，而非只看网站外观。'), point('报告动词传递立场', 'states 可报告明确说法；suggests 保留解释空间；claims 常让读者注意主张仍需检验。选择动词应对应内容，不为显得高级而替换。')],
        vocabulary: [vocab('credibility', '可信度', 'Credibility depends partly on the evidence provided.'), vocab('claim', '主张；声称', 'The claim is broader than the evidence.'), vocab('trace', '追溯', 'Trace the figure to its original source.')],
        reading: {title: 'Two descriptions of a study app', text: `This is a fictional teaching example. A university newsletter describes a new study app as “a promising tool for busy students”. It quotes the developer, who says that the app helps users organise their reading. The article includes a link to a demonstration but gives no information about how learning outcomes were measured. A student blog describes a different experience: the writer liked the reminders but stopped using the app because entering tasks took too long. The writer explains when and how the app was used, yet reports only one person's experience.

Neither source should be dismissed automatically. The newsletter is useful for finding the official features and contact details, while the blog raises a practical question about workload. However, neither establishes whether the app improves learning across a wider student population. A reader investigating that question would need evidence about relevant outcomes, participants and comparisons. The important issue is not which page looks more professional, but which source can support the particular conclusion the reader wants to draw.`, support: '分别写出两份来源的用途和局限。不要把“可用来了解功能”误写成“证明学习效果”。'},
        listening: {title: 'A librarian’s advice', text: `When you find a strong claim online, do not stop at the page that repeats it. Follow the link to the original report and check whether the report actually makes that claim. A headline may remove important conditions. For example, “students improved” tells us little unless we know which students, what improved, and how it was measured. A recent publication date is useful, but recent does not automatically mean well supported. Equally, an older source may still explain a stable concept accurately. In your notes, record the claim, the evidence and the limitation separately. That makes it easier to decide whether a source belongs in your argument, rather than collecting impressive-looking links that do not answer your question.`, focus: '听出评价来源的三个记录项，以及对“越新越好”的修正。'},
        questions: [question('reading', 'For which purpose is the newsletter most directly useful?', ['Establishing the app’s effect on all students.', 'Finding the official features and contacts.', 'Measuring how often students abandon it.'], 1, '该材料提供功能与联系方式，未提供学习结果测量。'), question('reading', 'What would be an unjustified conclusion?', ['The blog identifies a possible workload issue.', 'The two sources serve different purposes.', 'The professional-looking newsletter proves effectiveness.'], 2, '外观和校方发布身份不能代替针对效果的研究证据。'), question('listening', 'Why follow a claim to the original report?', ['To check whether the conditions and meaning were preserved.', 'To avoid reading any older publication.', 'To find a more attractive headline.'], 0, '二手标题可能删掉限制条件。'), question('listening', 'Which notes best support later source evaluation?', ['Author names without any claims.', 'Claim, evidence and limitation in separate fields.', 'Only the most confident sentences.'], 1, '这三项帮助判断来源是否支持当前论证。')],
        production: {writing: '写 180–220 词来源评价，说明两种材料各自能支持什么，再列出判断学习效果还需要的信息。', speaking: '用 2 分钟向组员解释为什么“有名的网站”不等于“能回答我们的问题”。', model: 'The newsletter establishes what the app offers, whereas the blog illustrates one user’s difficulty. Both are useful for planning questions, but neither tests learning outcomes in a wider group. Before recommending the app on educational grounds, we would need to examine the participants, outcome measures and comparison conditions in relevant research.', rubric: ['区分来源用途，未把单人经验或推广文字当效果证据', '准确用报告动词并指出至少一个缺失条件', '提出能解决当前问题的证据需求，而非笼统说多研究']},
        review: {prompt: '不用原文，给出三个追问来检验“这个软件让学生学得更好”；再说出新闻稿仍有什么用途。', answer: '追问对象、结果定义、测量与比较条件。新闻稿可核对官方功能、日期或联系渠道，不能单凭它推断学习效果。'}}),
      lesson({id: 'b2-claims-causality', title: '相关、原因与替代解释', skill: '研究阅读 · 限定', minutes: 40,
        goals: ['识别观察性比较无法自动支持因果的原因', '用合适限定词表达结果与替代解释'],
        explanation: [point('关联先回答一起变化', 'Students who attended scored higher 说明分组与得分有关联。谁选择参加、原有水平、其他支持都可能解释差异，不能直接写 attendance caused improvement。'), point('限定要有具体理由', 'may、appears to 不是装饰。写清为何不能确定：例如没有基线测量或没有合适比较。也不要把“未证明”写成“证明无效”。')],
        vocabulary: [vocab('association', '关联', 'The report describes an association, not a demonstrated cause.'), vocab('baseline', '基线；干预前参照', 'The groups differed at baseline.'), vocab('alternative explanation', '替代解释', 'Prior interest is an alternative explanation.')],
        reading: {title: 'A fictional workshop comparison', text: `This is a fictional teaching example. A department offered an optional writing workshop before an essay deadline. Students who attended received higher average marks than those who did not. A short internal report therefore described the workshop as successful. However, attendance was voluntary, and the department had not collected information about students' earlier writing performance. Some attendees may already have been more confident writers, or they may have had more time available for preparation. The observed difference alone cannot separate these possibilities from an effect of the workshop.

This does not establish that the workshop was useless. Participants' comments might still reveal which activities they found helpful, and the attendance figures could inform future planning. To investigate changes in writing more carefully, the department could collect comparable work before and after the workshop and consider how to form an appropriate comparison group. Any conclusions would still need to reflect the design and the students who took part. Evidence can be useful without answering every question.`, support: '把观察到的差异与至少两种可能原因分开。留意“不足以证明有效”不等于“证明无效”。'},
        listening: {title: 'What the report should say', text: `I would revise the conclusion rather than remove the report. We did observe higher marks among workshop attendees, so it is reasonable to describe that pattern. The problem is the next step: the current wording says the workshop produced the difference. We do not know that. It would help to know whether the groups had similar writing skills beforehand and whether they received other support. Asking participants whether they enjoyed the session is useful for improving the experience, but enjoyment is a different outcome from better writing. In the next round, we should decide what improvement means before collecting data. Otherwise, we may end up choosing whichever result makes the workshop look most successful.`, focus: '区分说话者保留的观察、删除的因果推断，以及新增的测量建议。'},
        questions: [question('reading', 'Which fact most directly limits a causal interpretation?', ['The workshop concerned writing.', 'Participation was voluntary and prior performance was unknown.', 'The report was short.'], 1, '自愿参加和缺少原有水平资料使组间差异存在替代解释。'), question('reading', 'Which conclusion is warranted?', ['The workshop definitely had no value.', 'All attendees improved because of it.', 'The observed difference requires cautious interpretation.'], 2, '数据既不能独自确证因果，也不能证明无价值。'), question('listening', 'Why is enjoyment insufficient as the only measure?', ['It is a different outcome from writing improvement.', 'Students are never able to report feelings.', 'The workshop had no participants.'], 0, '满意度与目标学习结果属于不同构念。'), question('listening', 'Why decide the outcome in advance?', ['To guarantee a positive result.', 'To reduce selective choice of a flattering result later.', 'To avoid using a comparison group.'], 1, '事先明确改进指标可减少事后挑选有利结果。')],
        production: {writing: '用 180–220 词改写内部报告结论：保留观察、给出两个替代解释、建议一种后续比较。', speaking: '做 2 分钟讲解，用一个生活例子说明“同时出现”与“导致”的不同。', model: 'Workshop attendees obtained higher average marks, but attendance was voluntary and earlier performance was not recorded. The difference may reflect prior ability or available study time as well as the workshop. A future evaluation should define writing improvement in advance and collect comparable baseline evidence, while also considering differences between participants and non-participants.', rubric: ['准确描述已观察的模式，没有改写为因果', '至少两个具体替代解释与研究设计相连', '后续建议对应缺失证据，未承诺必然解决所有偏差']},
        review: {prompt: '将“参加者分数更高，所以课程使他们提高”改成三句审慎英文：观察、限制、下一步。', answer: 'Attendees received higher marks. However, earlier performance was not measured, so the difference cannot be attributed to the workshop alone. Future evaluation should include comparable baseline work.'}}),
      lesson({id: 'b2-numbers-context', title: '解释数字、分母与比较', skill: '数据表达 · 阅读', minutes: 40,
        goals: ['区分比例、人数、百分点与相对变化', '判断汇总数字是否掩盖组别或时间差异'],
        explanation: [point('把分母写出来', '20 out of 50 与 20 out of 200 都有 20 人，但比例不同。描述增长先说明基期、终期和测量对象。'), point('百分点与百分比', '从 40% 到 50% 增加 10 个百分点；相对原值增加 25%。只有在同类人群和一致测量下，比较才具有相应用途。')],
        vocabulary: [vocab('proportion', '比例', 'A larger proportion completed the task.'), vocab('percentage point', '百分点', 'The rate rose by ten percentage points.'), vocab('denominator', '分母', 'The denominator is the number invited.')],
        reading: {title: 'A fictional library dashboard', text: `This is a fictional teaching example. A library dashboard reports that attendance at its introduction session doubled: twenty students attended in September and forty in October. The headline sounds impressive, but the invitation list also changed. In September, fifty students were invited; in October, two hundred received an invitation. Attendance increased in absolute numbers, while the proportion of invited students who attended fell from forty percent to twenty percent.

Neither measure is inherently wrong. The number attending may matter for staffing, whereas the attendance proportion may be relevant when judging whether invitations reached their intended audience. Even the proportion does not explain why students attended or stayed away. October invitations included a different programme with a timetable clash, so the two groups were not directly comparable. A useful report should present the count, the denominator and the relevant context together. It should also distinguish participation from learning: arriving at an introduction session is not evidence that a student can use the catalogue independently afterwards.`, support: '自己算出两个月的比例，再分别为人数和比例找一个合理用途。'},
        listening: {title: 'Reading a completion rate', text: `Our fictional training dashboard shows a completion rate rising from forty percent to fifty percent. You may hear this described as a ten-percent increase, but that wording is ambiguous. The difference is ten percentage points; relative to the original forty percent, it is a twenty-five-percent increase. Before celebrating either figure, check what “completion” means. This version of the dashboard counts opening the final page, not passing a task. We should label it accordingly. It is also worth asking whether the same group of learners was tracked both times. If people who found the course difficult stopped appearing in the records, a higher rate among the remaining users could give a misleading picture of the whole group.`, focus: '听出三种核查：变化单位、完成定义、是否同一群人。'},
        questions: [question('reading', 'What happened to the invitation-to-attendance proportion?', ['It fell from 40% to 20%.', 'It doubled from 20% to 40%.', 'It remained unchanged.'], 0, '20/50=40%，40/200=20%；人数增多与比例下降可同时成立。'), question('reading', 'Why might the attendance count still be useful?', ['It proves independent catalogue use.', 'It helps plan staffing requirements.', 'It eliminates differences between programmes.'], 1, '人数与接待资源相关，但不等于学习成效。'), question('listening', 'What is the change from 40% to 50%?', ['A 10% relative increase only.', 'A 25-percentage-point increase.', 'Ten percentage points, or 25% relative to the initial value.'], 2, '差为 10 点，相对变化 10/40=25%。'), question('listening', 'Why question the definition of completion?', ['Opening a page may not demonstrate task performance.', 'The final page was removed.', 'A percentage cannot describe participation.'], 0, '操作记录与能力表现不同，标签需准确。')],
        production: {writing: '写 180–220 词仪表板说明，分别报告两个阅读数字、指出比较限制，并解释“完成率”的测量问题。', speaking: '用 2 分钟向非技术同伴解释人数与比例为什么可能朝不同方向变化。', model: 'Attendance rose from twenty to forty, but the invitation list grew from fifty to two hundred. Thus, more people attended while the attendance proportion declined. These figures inform different decisions, and the programme mix also changed. Separately, opening the final page should be described as a usage event rather than evidence of successful learning.', rubric: ['人数、分母、比例与百分点计算准确', '说明指标适合哪种决定及至少一项比较限制', '清楚区分操作记录与实际能力，没有夸大学习结果']},
        review: {prompt: '不用原文计算 30/60 与 45/150；说出人数和比例各怎样变化，再解释从 20% 到 30% 的两种变化单位。', answer: '人数 30→45 增加，比例 50%→30% 下降。20%→30% 增加 10 个百分点，相对原值增加 50%。'}}),
      lesson({id: 'b2-argument-counterargument', title: '论证与反驳：回应最强顾虑', skill: '写作 · 论证', minutes: 40,
        goals: ['识别主张、理由、反对意见和回应', '用条件性建议避免虚假的二选一'],
        explanation: [point('反驳先公平呈现', '不要把对方说成明显愚蠢的观点。用真实顾虑建立回应：成本、访问需求、实施能力，之后说明如何处理或为何仍有取舍。'), point('政策建议可以有限定', 'Rather than require X in every case, allow it when... 提供条件方案。承认成本不会自动推翻主张，但必须解释成本由谁承担。')],
        vocabulary: [vocab('objection', '反对意见', 'The main objection concerns staff time.'), vocab('trade-off', '取舍', 'The proposal involves a trade-off.'), vocab('conditional', '有条件的', 'The committee offered conditional support.')],
        reading: {title: 'Should all talks include a recording?', text: `A student committee proposes recording every invited talk so that students with timetable clashes can watch later. The proposal has an obvious access benefit, but a blanket requirement may create problems. Some speakers discuss work that they are not ready to distribute, and others use material for which recording permission is unclear. A recording also needs captions and appropriate storage if it is to be genuinely useful.

These objections do not justify abandoning the access goal. Instead, the committee could request permission in advance and offer an alternative when a recording is unsuitable. A speaker might provide a short written summary or a separate question session. The department would also need to allocate time for checking captions rather than treating an automatic transcript as finished work. The strongest version of the proposal is therefore conditional: make accessible follow-up materials the default expectation, but agree on the appropriate format with each speaker. This approach preserves the aim while recognising practical responsibilities.`, support: '主张发生了什么调整？区分 access 的目标与 recording 这一实现手段。'},
        listening: {title: 'A committee member responds', text: `I support the revised proposal, with one reservation. If we offer alternatives, students must be able to find them easily. A written summary hidden in an email thread will not help someone who missed the talk. Could we use one course page for recordings, summaries and follow-up questions? We should also be clear about who maintains it. I am not suggesting that speakers should answer unlimited questions after every event. We could collect questions for a week and ask whether the speaker is willing to respond to a small selection. That would make the follow-up manageable. My concern is not the range of formats; it is whether the arrangement remains usable after the event has ended.`, focus: '判断发言者是否反对多种形式，以及其真正关注的落实条件。'},
        questions: [question('reading', 'What distinguishes the revised proposal?', ['It abandons access for absent students.', 'It treats recordings as the only acceptable format.', 'It keeps the access goal while allowing agreed alternatives.'], 2, '目标保留，实现形式根据情况协商。'), question('reading', 'Why are captions mentioned?', ['They create work that the proposal must account for.', 'They remove all permission concerns.', 'They make written summaries unnecessary.'], 0, '可访问性需要资源，不能把自动转写当完成。'), question('listening', 'What is the speaker’s main concern?', ['All speakers must answer unlimited questions.', 'The materials must remain easy to find and maintain.', 'Different formats should be prohibited.'], 1, '关注集中入口和维护责任，而非否定多种形式。'), question('listening', 'Why collect questions for one week?', ['To avoid allowing any questions.', 'To replace all recordings.', 'To bound the follow-up workload.'], 2, '限时收集、小量回应，使后续任务可管理。')],
        production: {writing: '写 220–260 词建议稿：明确目标，公平呈现一个强反对意见，给出回应及实施责任。', speaking: '做 2 分钟会议发言，先准确概括反对意见，再提出有条件的折中方案。', model: 'Access should be the goal, but compulsory recording is not always the appropriate means. Permission and captioning require advance planning. I recommend a shared page containing an agreed recording or summary, with a named coordinator responsible for maintenance. A limited question period would provide follow-up without imposing an unlimited obligation on speakers.', rubric: ['反对意见表述公平，回应针对真实顾虑', '主张、理由、让步和回应关系清晰', '建议说明条件和责任人，而非只有愿景']},
        review: {prompt: '用三句英文区分目标、手段和落实条件；再给“所有讲座必须录像”提出最强反对意见。', answer: 'The goal is access to missed talks. Recording is one possible format. Permission, captions and maintenance must be arranged. 强反对意见可涉及未公开研究或授权限制。'}}),
      lesson({id: 'b2-paraphrase-synthesis', title: '改写并综合两种观点', skill: '学术写作 · 归属', minutes: 45,
        goals: ['用自己的结构表达原意并保留限制', '围绕共同问题组织多个来源，而非逐篇罗列'],
        explanation: [point('改写不是逐词换同义词', '先理解、合上原文、按自己的句子结构表达，再核对范围和立场。引用他人观点仍需归属；练习中的虚构来源不能放入真实参考文献。'), point('找关系而非强行一致', '先比较来源谈的对象和条件。可写 A concerns access, whereas B concerns workload；不同重点可能互补，并非互相推翻。')],
        vocabulary: [vocab('paraphrase', '保留原意的改写', 'A paraphrase still needs attribution.'), vocab('overlap', '重合；共同部分', 'The arguments overlap on access.'), vocab('emphasis', '强调重点', 'The two accounts differ in emphasis.')],
        reading: {title: 'Two fictional notes on group work', text: `These are fictional teaching sources, not published studies. Note A, written by “Lin” for this exercise, argues that group projects can give students opportunities to explain ideas to one another. It also warns that this opportunity is uneven when a confident member controls the discussion. The note recommends assigning a rotating discussion role rather than leaving participation entirely to chance.

Note B, written by “Reed” for this exercise, focuses on scheduling. It argues that a demanding group assignment can disadvantage students whose paid work leaves little common meeting time. Reed recommends agreeing on a realistic schedule and allowing some contributions to be prepared asynchronously.

The notes do not establish that group work is always better or worse than individual work. They identify different conditions that may affect how a group task functions. A useful synthesis would connect participation inside meetings with access to meetings: a student needs both a reasonable chance to attend and a meaningful opportunity to contribute. Treating the notes as a simple disagreement would hide that connection.`, support: '画两列：会内参与、会外时间条件。两位虚构作者并没有回答同一个完全相同的问题。'},
        listening: {title: 'Feedback on a draft synthesis', text: `Your draft accurately summarises both notes, but the paragraphs still read like two separate book reports. Try beginning with the question that connects them: what makes participation possible? Then explain how one note concerns the distribution of speaking opportunities and the other concerns access to shared time. Do not write that the authors proved group work improves learning, because neither note presents that evidence. You can make your own recommendation, but signal that it is your conclusion from the comparison. For instance, you might propose combining rotating roles with an agreed schedule. Also, keep the label that these are fictional teaching sources. We are practising attribution here, not creating references that can be used in a real assignment.`, focus: '听出“总结准确但综合不足”的具体含义，以及怎样标明自己的结论。'},
        questions: [question('reading', 'What relationship best connects the two notes?', ['They address different conditions for meaningful participation.', 'They prove opposite effects on grades.', 'They both reject all group assignments.'], 0, '一个关注会内机会，一个关注能否参与安排。'), question('reading', 'Which paraphrase preserves Note A’s qualification?', ['Group work guarantees equal speaking time.', 'Group work can create explanation opportunities, but these may be uneven.', 'Confident students should never join groups.'], 1, '保留 can 和机会分配不均的条件。'), question('listening', 'What is missing from the draft?', ['More copied sentences from each note.', 'A claim that both authors ran experiments.', 'An organising question that makes the relationship explicit.'], 2, '逐篇总结需改为围绕共同问题展开。'), question('listening', 'How should a combined recommendation be presented?', ['As the student’s inference from the comparison.', 'As a quotation spoken by both authors.', 'As a verified finding from published research.'], 0, '综合后的建议属于写作者的推论，需与来源原话区分。')],
        production: {writing: '写 220–260 词综合段，围绕 participation 比较两份虚构笔记，提出自己的建议；保留虚构来源标签。', speaking: '用 2 分钟解释两来源的互补关系，并回答“这是作者结论还是你的推论？”', model: 'In these fictional notes, participation depends on both access and interaction. Lin addresses unequal opportunities within discussion, whereas Reed examines the scheduling barriers that may prevent attendance. Taken together, these concerns support my recommendation to combine rotating roles with a realistic timetable. This is a proposed arrangement, not an established effect on learning.', rubric: ['用自己的结构准确表达原意和限制，明确观点归属', '围绕共同问题解释至少一处关系，而非只逐篇总结', '自己的建议与来源结论分开，虚构材料未伪装成真实研究']},
        review: {prompt: '不看原文说出 summary 与 synthesis 的区别；用一段两句英文连接“发言机会”与“安排时间”。', answer: 'Summary 概括各来源；synthesis 围绕问题解释它们的关系。例：Meaningful participation requires access to meetings as well as a chance to speak within them. The two fictional notes therefore address complementary conditions.'}}),
      lesson({id: 'b2-academic-word-building', title: '学术词族、名词化与清晰表达', skill: '构词 · 句法', minutes: 40,
        goals: ['拆解抽象名词并恢复动作与执行者', '在专业表达与读者可理解性之间调整'],
        explanation: [point('名词化压缩信息，也可能隐藏人', 'evaluate → evaluation，interpret → interpretation。The evaluation of responses 适合谈一个过程；要说明谁做什么，可改成 The team evaluated the responses。两种结构各有用途。'), point('词缀与重音一起核对', '不能假设同族词重音不变。analyse/analyze、analysis、analytical 的主重音不同；词典核对整词，构词帮助理解但不能独自给出准确读音。')],
        vocabulary: [vocab('evaluation', '评价；评估过程', 'The evaluation used two kinds of evidence.'), vocab('interpretation', '解释；阐释', 'The interpretation depends on the context.'), vocab('implementation', '实施', 'Implementation requires a clear timetable.')],
        reading: {title: 'Making a project note clearer', text: `A project note begins, “The implementation of the evaluation of student responses will be undertaken next month.” The sentence sounds formal, but a reader may struggle to find the action. Who will do the work, and what exactly will happen? The project schedule identifies two tutors as responsible. A clearer version is, “Next month, two tutors will evaluate the students' responses.” This revision identifies the people and restores the main action to the verb.

Nominalisation is not always a problem. Later in the report, “the evaluation” can efficiently refer to the whole process without repeating every detail. The decision depends on what the reader already knows and what the sentence needs to do. Similarly, the word “reassessment” suggests another assessment, but it does not tell us whether the same criteria will be used. That information must come from the context. Recognising word parts helps a reader form an initial hypothesis; checking the surrounding sentences determines how the term functions in this particular project.`, support: '给第一句圈出抽象名词，改写时补上执行者。再找出作者为何没有建议删除所有名词化。'},
        listening: {title: 'Preparing to say a technical term', text: `Before presenting, choose the technical words that your audience needs to hear clearly. Learn each word in a sentence, not only as a spelling list. For example, knowing “analysis” on a page does not guarantee that you will recognise it in a lecture or place its stress clearly in your own talk. Check a reliable dictionary, listen to the whole word and practise it inside a short explanation. Do the same for related forms rather than assuming the stress stays in one place. During the presentation, introduce an unfamiliar term with a plain-language explanation. You can then reuse the precise term once listeners know what it means. The goal is accurate communication, not replacing every ordinary word with a longer one.`, focus: '听出词形、读音与使用语境三者怎样结合；不要把合成朗读当真人发音评分。'},
        questions: [question('reading', 'What improves in the revised sentence?', ['Every noun is removed.', 'The actor and main action become explicit.', 'The evaluation is cancelled.'], 1, 'two tutors 与 evaluate 明确谁执行什么动作。'), question('reading', 'What does “reassessment” alone fail to tell us?', ['Whether assessment is involved.', 'That another assessment is suggested.', 'Whether the same criteria will be used.'], 2, 're- 提示再次，但不包含具体评估标准。'), question('listening', 'Why practise related forms separately?', ['Stress may change within a word family.', 'They always have unrelated meanings.', 'Only the longest form is acceptable.'], 0, '同词族并不保证相同重音位置。'), question('listening', 'How should an unfamiliar technical term be introduced?', ['Without context to test the audience.', 'With a plain-language explanation before reuse.', 'Only in a written appendix.'], 1, '先帮助听者建立含义，再使用精确术语。')],
        production: {writing: '写 180–220 词解释一次项目评估，先用清楚的主语和动词，之后合理使用 evaluation、interpretation 等回指。', speaking: '用 2 分钟解释一个本专业术语；查词典标出词重音，再给非专业听众一个例子。', model: 'Two tutors will evaluate the responses next month. They will first agree on the criteria and discuss several examples. The evaluation will identify issues that need further attention, but its interpretation will depend on the tasks used. Here, “criteria” means the standards against which each response is considered.', rubric: ['重要动作有明确执行者，名词化用于压缩已知信息', '技术词有准确的语境解释，词缀推测经过核对', '口述准备包含词典重音记录和一个听众可理解的例子']},
        review: {prompt: '把 The implementation of the review was completed by the team 改成直接句；再说出名词化何时仍有用途。', answer: 'The team completed the review. 名词化可回指整个已说明的过程，或把过程作为讨论对象；不是所有名词都应删除。'}}),
      lesson({id: 'b2-lecture-structure', title: '跟随讲座结构，提出有用问题', skill: '听力 · 研讨', minutes: 40,
        goals: ['识别讲者的主张、例子、限制与转向', '提出能推进讨论的具体澄清或应用问题'],
        explanation: [point('笔记按功能组织', '用 claim / example / limitation / question 分类，避免逐字抄。An example illustrates a point, but may not demonstrate a general pattern。'), point('问题连接讲者论证', '先准确概括，再问适用条件或证据：You distinguish X from Y. How would that apply when...? 避免把不同意伪装成无关长篇发言。')],
        vocabulary: [vocab('distinction', '区别', 'The distinction matters for interpretation.'), vocab('illustrate', '举例说明', 'This case illustrates the problem.'), vocab('implication', '含义；可能带来的影响', 'What is the implication for small classes?')],
        reading: {title: 'Notes from a fictional seminar', text: `In a fictional seminar on feedback, a lecturer distinguishes comments that identify a problem from comments that help a learner decide what to do next. “Unclear” identifies a reader's difficulty, but it does not indicate whether the problem concerns organisation, evidence or vocabulary. A more useful comment may ask the writer to explain how one example supports the main claim.

The lecturer does not argue that every comment must contain a complete solution. Too much direction can leave little work for the learner. Instead, she asks students to consider whether the recipient has enough information to take a meaningful next step. This depends partly on experience: a brief prompt may be sufficient for one student and confusing for another. After the seminar, a participant proposes replacing all short comments with long explanations. That proposal misses the distinction. Length is not the central issue; the relationship between the comment, the task and the learner's available knowledge is.`, support: '讲者区分的是反馈功能，不是简单的长短。用这一点判断课后提议为何偏离主旨。'},
        listening: {title: 'A lecture on using feedback', text: `Let me move from receiving feedback to using it. A student can collect many comments and still make no revision. The important question is what happens between reading a comment and changing the work. Imagine a tutor writes, “Explain your comparison.” The student first needs to identify the two things being compared. Next, they need to decide which shared criterion matters. Only then can they revise the paragraph. This example illustrates a process; it does not show that the same sequence is appropriate for every assignment. In a mathematical proof or a design portfolio, the next step may look different. When you review feedback, write one possible action beside each important comment, and check whether that action addresses the reader’s concern.`, focus: '按“转向—示例步骤—范围限制—行动建议”记四行笔记。'},
        questions: [question('reading', 'Why does “replace all short comments with long ones” miss the point?', ['All short comments are already perfect.', 'The lecture concerns useful next steps, not length alone.', 'The lecturer prohibited explanations.'], 1, '有效性取决于任务与学习者知识，不单取决于字数。'), question('reading', 'What determines whether a brief prompt is enough?', ['Only the tutor’s preferred font.', 'Whether the assignment is printed.', 'The learner’s experience and relevant knowledge.'], 2, '同一提示对不同经验者可能作用不同。'), question('listening', 'What is the example intended to do?', ['Illustrate how a comment can lead to an action.', 'Prove every subject uses the same revision sequence.', 'Replace the need to read feedback.'], 0, '讲者明确说示例说明过程，并不普遍化到所有学科。'), question('listening', 'Which question best extends the talk?', ['Can we ignore all brief comments?', 'How could we identify a useful next step in a design portfolio?', 'Why must every paragraph compare exactly two items?'], 1, '把已述原则应用到讲者承认可能不同的场景。')],
        production: {writing: '写 180–220 词讲座概括，区分主旨、例子与限制，并提出一个应用问题。', speaking: '模拟研讨发言 2 分钟：先概括对方，再提出问题，并给自己一个可能的回应。', model: 'The lecturer focuses on converting comments into meaningful actions. The comparison example shows how a learner might identify objects and criteria before revising. However, the sequence is not presented as universal. My question is how a student can choose an appropriate next step when the feedback concerns a design decision rather than a written argument.', rubric: ['主旨、例证和限制明确分开，未把例子当普遍证明', '问题与讲者已有观点相连且具体可讨论', '口述有简短准确概括，问题本身清楚而不过长']},
        review: {prompt: '闭卷列出听讲座时的四种信息功能；用两句英文说明为什么“更长的反馈”未必更好。', answer: '可记录主张、例子、限制、问题/行动。A longer comment is not necessarily more useful. It must help this learner identify an appropriate next step for this task.'}}),
      lesson({id: 'b2-proposal', title: '写出可评估的项目建议', skill: '综合 · 项目提案', minutes: 45,
        goals: ['把问题、方案与评估指标对应起来', '区分可行性、体验与效果的证据'],
        explanation: [point('先写需要改变什么', 'Aims 要指向具体需要；activities 是为目标设计的动作；indicators 说明如何判断实施或结果。三者要对齐。'), point('小型试行可以回答有限问题', 'Pilot 可先检验能否实施与流程问题，未必有足够证据回答普遍效果。说明不能回答什么有助于合理使用结果。')],
        vocabulary: [vocab('feasibility', '可行性', 'The pilot will examine feasibility.'), vocab('indicator', '指标', 'Attendance is an indicator of reach.'), vocab('scope', '范围', 'The proposal has a limited scope.')],
        reading: {title: 'A fictional peer-support proposal', text: `This is a fictional teaching proposal. A department wants to help new students ask questions about unfamiliar assignment instructions. It plans a four-week peer-support session in which trained volunteers explain task wording without writing answers for students. The proposal initially lists success as “better academic results”. That aim is too broad for the information the team intends to collect: attendance records and a short satisfaction form.

A revised proposal separates three questions. Can the department recruit volunteers and run the sessions reliably? Do attendees feel able to ask questions? Can students explain the assignment requirements more accurately afterwards? The first concerns feasibility, the second concerns experience, and the third concerns a specific learning outcome. Each requires different evidence. The team could use scheduling records, anonymous feedback and a short explanation task. Even then, a small voluntary pilot would not establish that the programme improves all academic results. Its more modest purpose is to identify whether the arrangement is workable and worth evaluating further.`, support: '将三个问题分别与证据配对。注意“成绩更好”与当前指标之间为什么不匹配。'},
        listening: {title: 'A supervisor challenges the plan', text: `The revised proposal is clearer, but I would like two points addressed before the pilot begins. First, volunteers need a boundary: they may clarify instructions, but they should refer questions about grading decisions to the tutor. Otherwise, students may receive confident answers from people who are not authorised to make those decisions. Second, describe how you will use the explanation task. If you only ask students afterwards, you will not know whether they already understood the instructions before the session. A brief initial task would provide useful context, although it would not remove every limitation of a voluntary pilot. Please also say who will review the records and when the team will decide whether to continue.`, focus: '听出角色边界、前测需求与决策责任三项补充。'},
        questions: [question('reading', 'Why is attendance alone insufficient for the original success claim?', ['It cannot by itself establish better academic results.', 'It never helps any planning decision.', 'It is the same as a writing score.'], 0, '到场记录衡量覆盖或实施，不直接测学术表现。'), question('reading', 'Which measure best fits understanding assignment requirements?', ['The colour of the feedback form.', 'A task asking students to explain the requirements.', 'The number of available chairs.'], 1, '测量任务与具体学习目标对齐。'), question('listening', 'What should volunteers do with questions about grading decisions?', ['Invent a likely answer.', 'Change the marking criteria.', 'Refer them to the tutor.'], 2, '明确授权与职责边界，不能由志愿者作评分决定。'), question('listening', 'Why add an initial explanation task?', ['To establish what students understood before support.', 'To guarantee the pilot proves causation.', 'To eliminate the need for later evaluation.'], 0, '基线提供原有理解的信息，但不能消除所有设计局限。')],
        production: {writing: '写 240–280 词试行提案，包括目标、活动、三类指标、职责边界、限制与继续/调整的决策点。', speaking: '做 3 分钟提案陈述，再回答“这项试行能证明什么，不能证明什么？”', model: 'The pilot will test whether peer support can be delivered reliably and whether attendees can explain instructions more accurately afterwards. Volunteers will clarify wording but refer grading questions to tutors. Scheduling records, feedback and brief before-and-after tasks will address different questions. Because participation is voluntary and the scope is small, the findings will guide revision rather than establish effects on overall academic achievement.', rubric: ['目标、活动和证据一一对应，没有用满意度替代学习成效', '明确角色、时间与审阅责任，方案可以实际执行', '保留自愿参加及规模局限，决策建议与证据强度相称']},
        review: {prompt: '从记忆区分 feasibility、experience、learning outcome，各给一个指标；再给志愿者写一句职责边界。', answer: '可行性看排班是否执行，体验用匿名反馈，理解用解释任务。Volunteers clarify the wording but refer grading decisions to the tutor.'}})
    ],
    assessment: assessment('b2', {
      reading: {title: 'Fictional policy brief: a shared equipment desk', text: `This is a fictional teaching example. A faculty is considering a shared equipment desk so that students from different departments can borrow cameras and microphones. At present, each department manages its own stock. A planning note argues that a common desk would make unused equipment easier to find. It also acknowledges that a single location could be less convenient for students whose classes are held far away.

The note cites an internal trial involving two departments. During a three-week period, staff listed spare microphones on a shared page, and several bookings crossed departmental boundaries. The planning team treats this as evidence that cross-departmental borrowing is possible. It does not yet have data on travel time, staff workload or students who chose not to borrow. A separate student response welcomes easier access but warns that a central desk with limited opening hours could create a new barrier for students with employment or care responsibilities.

One administrator proposes opening the common desk immediately and judging success by the total number of loans. Another suggests a six-week pilot with a collection point in each participating building. Under the second proposal, the team would record loan numbers, waiting times and unsuccessful requests, while also asking users and non-users about access. Neither proposal has an agreed staffing budget. The student response therefore recommends deciding who will maintain the booking system before expanding it.

The central question is not simply whether sharing equipment sounds efficient. The faculty needs to distinguish making stock visible from making it accessible. A large number of loans could coexist with long waits or unequal access. The internal trial supports further investigation, but its narrow scope does not establish that one permanent location would serve the whole faculty well.`, support: '新材料。区分现有证据支持的“可发生”与未来政策所需的“适合全面实施”。'},
      listening: {title: 'A consultation meeting on the equipment desk', text: `I favour a pilot, but I do not think we should change every part of the system at once. If we change the website, collection points and opening hours simultaneously, it may be difficult to understand which problems a later complaint refers to. That does not mean we must test each feature in isolation. It means our records need enough detail to connect a difficulty with the stage at which it occurred. For instance, a student might find a microphone online but fail to collect it because the desk closes before their class ends.

I also want to clarify the proposed satisfaction question. Asking only successful borrowers whether they liked the service leaves out people who gave up. We should offer a short feedback route on the booking page and invite comments from students who did not complete a loan. Finally, please do not describe the trial as cost-saving yet. We have counted loans, but we have not counted the staff hours required to arrange them. A useful review would report both access and workload, then recommend which parts to retain or revise.`, focus: '听出反对意见的范围、遗漏的人群，以及尚不能使用的成本结论。'},
      questions: [question('reading', 'What does the initial trial most directly establish?', ['A permanent central desk saves money.', 'Cross-departmental borrowing can occur through a shared listing.', 'All students prefer one collection point.'], 1, '现有试行仅表明跨院系借用实际发生，不能覆盖成本或全体偏好。'), question('reading', 'What do the planning note and student response have in common?', ['Both reject all equipment sharing.', 'Both assume travel time is irrelevant.', 'Both recognise access concerns beyond stock visibility.'], 2, '计划说明地点不便，学生回应补充开放时间等障碍。'), question('reading', 'Why are loan counts insufficient as the sole success measure?', ['High use can coexist with delays and excluded users.', 'Counts cannot ever describe demand.', 'Every loan is unsuccessful.'], 0, '总量不能显示等待或没有完成借用的人。'), question('reading', 'Which information would most directly address the implementation gap?', ['More photographs of cameras.', 'An agreed allocation of staffing and maintenance responsibilities.', 'A claim that efficiency is always desirable.'], 1, '预算与维护责任均未明确，是实施缺口。'), question('listening', 'What is the speaker’s position on changing several features?', ['It must never happen under any conditions.', 'It automatically proves which feature caused every outcome.', 'It can happen, but records must locate where difficulties arise.'], 2, '讲者明确不是要求所有特征分开测试，而是细化过程记录。'), question('listening', 'Whose views are missing from a survey of successful borrowers?', ['People who gave up before completing a loan.', 'Staff who counted completed loans.', 'Students who collected equipment on time.'], 0, '仅问成功者会遗漏尝试失败或放弃者。'), question('listening', 'Why avoid describing the trial as cost-saving?', ['The desk has no microphones.', 'Staff hours have not been counted.', 'The speaker opposes all budgeting.'], 1, '尚无完整投入数据，不能声称节约成本。'), question('listening', 'Which review would best match the speaker’s recommendation?', ['A list of favourable comments only.', 'A ranking based solely on total loans.', 'A report connecting access problems, workload and possible revisions.'], 2, '对应讲者对阶段性障碍和人员工作量的共同关注。')],
      writing: '写 280–320 词给院系的建议，综合两份新材料；提出有条件的方案、证据需求和一项合理反对意见，解释现有试行不能支持什么结论。',
      speaking: '做 3 分钟简报，说明“可见”与“可及”的区别，并回应：“借用次数多，为什么还不能证明成功？”保存口述提纲或实录。',
      rubric: ['准确综合阅读与听力，区分事实、推论和建议', '论证处理反对意见与实施责任，指标与目标匹配', '语言连贯、措辞审慎，口述重点易跟随且能解释术语'],
      model: '参考片段：The initial trial demonstrates that shared listings can support cross-departmental borrowing, but it does not establish the suitability of one permanent desk. A pilot should track the stages at which access fails, include non-users and record staff time. Although multiple collection points may add workload, this concern should be measured alongside travel and opening-hour barriers. Loan totals alone cannot capture these trade-offs.'
    })
  };
  const c1 = {
    id: 'c1', label: 'C1', title: '学术理解、论证与研究交流',
    description: '在较长材料中追踪论证、判断证据与限制，综合不同来源，并以清楚而审慎的语言参与研究讨论。案例中的机构、研究和数据均为原创虚构教学材料。',
    canDo: ['理解复杂长文与短讲中的隐含立场、限定与论证结构', '综合来源、准确归属观点，写出组织清楚且有条件的论证', '在研讨中澄清概念、回应反对意见，并解释方法和局限'],
    sources: [sources.cefr, sources.cautious, sources.synthesis, sources.paraphrase, sources.stress],
    foundations: [{course:'word-parts',lessonId:'compounds-families-and-stress',label:'词族变化与重音'}, {course:'word-parts',lessonId:'abstract-and-person-nouns',label:'抽象名词与学术构词'}, {course:'phonics',lessonId:'syllables-stress-schwa',label:'多音节与弱读'}, {course:'word-parts',lessonId:'combine-and-check',label:'拆词之后用语境验证'}],
    lessons: [
      lesson({id:'c1-academic-word-building',title:'词根词缀进阶：把抽象名词还原成论证',skill:'学术构词 · 信息结构',minutes:45,
        goals:['在语境中区分观察、解释、推论等词族功能','将密集名词结构还原为谁做了什么，不改变限定条件'],
        explanation:[point('词尾提示功能，不能替代定义','interpret → interpretation → interpretive 可以帮助识别动词、名词和形容词。名词化把过程当作对象讨论，也可能隐藏行为者。将 the interpretation of results 改写为 researchers interpreted the results 时，要核对原文是否真的说明了行为者。'),point('把构词接到论证层级','observation 是观察；interpretation 是解释；implication 是可能意义。不要因为它们都是抽象名词就把它们当作同等强度的证据。operationalisation 指把概念落实成可观察的操作或指标，具体定义仍由研究提供。')],
        vocabulary:[vocab('interpretation','解释；对材料赋予意义','An interpretation should be distinguished from an observation.'),vocab('operationalisation','操作化；把概念落实为测量方式','The operationalisation of participation relied on message counts.'),vocab('implication','可能的意义或影响；不是必然结果','The implication for teaching remains uncertain.')],
        reading:{title:'When a noun conceals a decision — fictional teaching case',text:`A fictional university report describes an increase in student engagement after the introduction of an online discussion board. The sentence sounds straightforward until the reader asks how engagement was operationalised. The researchers counted posts, but did not examine whether the posts contained questions, explanations or copied instructions. The observation is therefore an increase in posting, while the interpretation concerns a broader concept.
Nominalisation makes it possible to discuss these processes compactly. However, phrases such as the enhancement of engagement can present an interpretation as though it were already an established event. Replacing the noun phrase with a clause exposes the missing decision: someone judged that more posts indicated greater engagement. The report should explain who made that judgement and why the indicator was appropriate.
This does not mean that nominalisations should be removed from academic writing. Terms such as measurement and interpretation allow writers to connect ideas across several sentences. The difficulty arises when compression hides uncertainty or agency. A careful revision might state that posting increased during the trial and that this change may indicate one aspect of participation. It should then acknowledge alternative explanations, including a new requirement to contribute every week. The wording becomes more precise because the grammatical structure now reflects the distinction between what was counted and what was inferred.`,support:'分别标记计数对象、抽象概念和推论。不要把 engagement 自动翻译成已经证明的学习投入提高。'},
        listening:{title:'A supervisor asks for a clearer claim',text:`This is a fictional supervision conversation. Your paragraph says that implementation produced improvement, but both nouns need attention. Implementation tells me that something was introduced; it does not tell me whether students used it consistently. Improvement tells me that you have chosen a desirable outcome, yet the paragraph never identifies the comparison. I would begin with the observation: more students posted during the trial than during the previous month. Then I would state the interpretation separately. Perhaps the board made contribution easier, but the new weekly posting rule offers another explanation. You can still use the noun participation later, once you have defined it. Notice that I am not asking you to replace every long word with a short one. I am asking you to make the reasoning visible. A precise technical term can be helpful; a familiar word can be misleading when its meaning shifts between sentences.`,focus:'导师反对的是长词本身，还是隐藏的推理？记录他要求补充的比较和替代解释。'},
        questions:[question('reading','In the fictional report, what is directly observed?',['Greater motivation in every student.','An increase in recorded posts.','A proven improvement in learning.'],1,'实际计数是 posts；投入与学习效果需要另外的证据。'),question('reading','Why does rewriting a nominalisation as a clause help here?',['It can expose agency and an unstated judgement.','It guarantees that the conclusion is causal.','It removes the need to define technical terms.'],0,'改成句子便于追问谁解释了什么，但不能凭语法补足证据。'),question('listening','Which comparison does the supervisor explicitly propose?',['One university against all other universities.','Frequent users against successful graduates.','Posting during the trial against the previous month.'],2,'比较时段在导师建议句中明确给出。'),question('listening','What is the supervisor’s position on technical vocabulary?',['All long words should be replaced.','Precision matters more than word length.','Familiar terms cannot be misleading.'],1,'导师保留精确术语，并指出常用词若含义变化也会误导。')],
        production:{writing:'写 220–280 词，改写本案例结论。明确观察、解释、操作化指标和一个替代解释；说明一次名词化保留或改写的理由。',speaking:'用 2 分钟向同学解释 engagement 与 post count 的区别，再回应“长词显得更学术”的说法。',model:'参考结构：The trial recorded more posts, but this finding does not by itself establish greater engagement. Posting frequency was the chosen indicator; it did not capture the quality or purpose of contributions. The weekly requirement is a plausible alternative explanation. I retain interpretation as a technical noun while rewriting enhancement of engagement to avoid presenting an inference as an observed outcome.',rubric:['准确区分直接观察、抽象概念和解释','词族形式与句法位置一致，未因改写添加原文没有的事实','口述能用通俗解释说明指标局限，同时保留恰当术语']},
        review:{prompt:'不看课文，解释 observation、interpretation、implication 的区别；把 the improvement of participation 改成一条有范围限制的英语结论。',answer:'区分计数事实、赋予意义和可能影响。例：Posting increased during the trial; this may reflect one aspect of participation, although the weekly requirement could also explain the change.'}}),
      lesson({id:'c1-prosody-and-lectures',title:'拼读进阶：词族重音、意群和讲座转折',skill:'发音 · 讲座听力',minutes:45,
        goals:['区分词内重音与句子焦点，不按构词边界机械停顿','通过路标和修正语追踪讲座中观点的变化'],
        explanation:[point('词族会改变重音','PHOtograph 与 phoTOGraphy 的重读位置不同。大小写这里只标主重音，不是完整音标。遇到新派生词用词典确认读音；词缀、拼写块和口语音节边界并不总一致。'),point('从单词走向意群','在自然停顿处划分意义单位，例如 The figures describe attendance / not learning gains。句中 not 提示对比。设备语音能提供整段练习，但不保证示范你设计的对比重音，仍需听真人材料并请人反馈可理解度。')],
        vocabulary:[vocab('qualification','对断言的限定；也可指资格','The lecturer added a qualification to the claim.'),vocab('emphasis','强调；突出的重点','The emphasis was on access rather than speed.'),vocab('reformulate','重新表述','She reformulated the question after a challenge.')],
        reading:{title:'Following a lecturer’s changing position',text:`In a graduate seminar, understanding each technical word is not always enough to follow an argument. A speaker may introduce a claim, distance themselves from it, and then restate a narrower version. Listeners who write only nouns can miss these relationships. A note containing access, speed and success gives little indication of which idea was supported and which was challenged.
Consider this invented seminar statement: The service was faster, but speed was not our principal measure of success. The contrast changes the function of the first clause. It remains a finding, yet it is not the basis of the main conclusion. Later, a phrase such as more precisely may signal a correction to an earlier formulation rather than a completely new topic. Notes should capture that change instead of preserving the first claim unchanged.
Pronunciation contributes to this structure. Word stress helps listeners identify words, while sentence focus and pauses can highlight a contrast or mark a transition. These patterns are flexible, and a listener should use syntax and context as well as sound. A practical method is to divide notes into claim, qualification and consequence. After listening, reconstruct the relationship in a short paragraph. Then compare it with the transcript, checking especially whether you turned a possibility into a fact or treated a supporting example as the speaker's final position.`,support:'把笔记分成 claim、qualification、consequence 三栏。重点记录 but、not、more precisely 等词改变了什么。'},
        listening:{title:'A distinction inside a short lecture',text:`The following lecture is an invented practice recording. Our redesigned advice desk certainly processed requests more quickly. At first, we described that change as improved access. More precisely, it improved the speed of handling requests that had already reached us. That qualification matters. We did not observe the people who gave up before entering the queue, and a faster response tells us little about their experience. I would therefore distinguish efficient processing from accessible service. The two may reinforce each other, but they are not interchangeable. When you summarise this discussion, please retain the positive result: the queue moved faster. Do not remove it simply because the evaluation has limitations. Equally, do not turn that result into a claim about everyone in the community. The next question is how to find out who never entered the queue and what prevented them from doing so. Interviews may help us formulate that question more carefully.`,focus:'听到 More precisely 后，把最初的 improved access 修正为何种更窄的结论？'},
        questions:[question('reading','What is lost when lecture notes contain only technical nouns?',['The spelling of those nouns.','The relationship between claims and qualifications.','The number of topics mentioned.'],1,'只列关键词无法保留支持、转折或修正的关系。'),question('reading','What does more precisely signal in this reading?',['A possible refinement of an earlier formulation.','A guarantee that every earlier sentence was false.','An instruction to copy the next sentence exactly.'],0,'它可能缩小或澄清前述说法，不等于整段推翻。'),question('listening','Which positive finding does the lecturer retain?',['All community members gained access.','Interviews established why non-users stayed away.','Requests reaching the desk were processed faster.'],2,'保留队列处理速度提高，同时不泛化到未进入队列的人。'),question('listening','Which distinction organises the lecturer’s argument?',['Written notes versus spoken notes.','Efficient processing versus accessible service.','Technical language versus everyday vocabulary.'],1,'讲座核心是处理效率不等于可及性。')],
        production:{writing:'写 220–260 词的讲座摘要，保留正面结果、修正后的结论、遗漏人群和下一步问题。',speaking:'为摘要划分意群；标出一个句子焦点。朗读两遍，再口述解释为何在该处强调。查词典核对 photograph/photography 的重音。',model:'参考片段：The redesigned desk processed incoming requests faster. The lecturer qualified the initial claim about access because people who never joined the queue were not observed. Efficient processing may contribute to accessibility, but the evidence does not establish that connection for non-users. An appropriate next step is to investigate barriers before queue entry.',rubric:['摘要保留转折与限定，没有删除真实的正面结果','口述按意义组织停顿，关键对比能够听清','词族重音经词典核对，反思记录指出一个需要继续练习的位置']},
        review:{prompt:'不看材料，复述讲座被修正的结论。再用一句 not...but... 或 although... 说明两个评价维度。',answer:'最初泛称 improved access，后改为处理已到达请求更快。例：Although processing became faster, access for people who never joined the queue remains unknown.'}}),
      lesson({id:'c1-causal-reading',title:'批判阅读：相关、机制与因果',skill:'阅读推理 · 证据评价',minutes:50,
        goals:['识别选择偏差与替代解释如何影响因果结论','提出能区分解释的进一步证据，而非笼统要求更多研究'],
        explanation:[point('先列设计，再读结论','追问谁参加、如何分组、何时测量和比较什么。一个可能的作用机制不能自动排除其他机制；统计差异也不自动解释差异来源。'),point('批评需要有针对性','用 The design leaves open the possibility that... 指出未排除的解释，再说明收集什么信息可以改善判断。批评不能把“尚未证明有效”改写成“已经证明无效”。')],
        vocabulary:[vocab('self-selection','自我选择参加所造成的组间差异风险','Self-selection may partly explain the difference.'),vocab('plausible mechanism','合理但仍需验证的作用机制','The proposed mechanism is plausible, not established.'),vocab('alternative explanation','替代解释','Prior preparation is an alternative explanation.')],
        reading:{title:'An optional writing workshop — fictional study',text:`In this fictional study, students who attended an optional writing workshop submitted higher-rated essays than students who did not attend. The organisers suggested that the workshop improved academic writing. Their proposed mechanism was plausible: participants practised organising claims and received feedback on draft paragraphs. However, the comparison did not begin with equivalent groups.
Attendance was voluntary, and students already interested in revising their work may have been more likely to participate. The researchers had no initial writing sample with which to compare the groups. They also evaluated only submitted essays. Students who withdrew from the course were absent from the analysis, even though withdrawal might be related to the difficulties the workshop was intended to address.
These limitations do not show that the workshop was ineffective. They restrict what can be inferred from the observed difference. A useful follow-up would obtain an initial writing sample, document participation and withdrawal, and explain how essays were rated. If access had to be allocated because places were limited, a fair and ethically appropriate allocation procedure could also create a more informative comparison.
The practical decision is therefore not simply whether to accept or reject the programme. A department might continue offering a small workshop while evaluating it more carefully. In reporting that decision, the writer should distinguish an educational rationale for offering support from a causal conclusion about the support's effects.`,support:'分开写“观察到差异”“机制假设”“设计遗漏”。无效与未证实有效是不同结论。'},
        listening:{title:'A reviewer asks for a better comparison',text:`This is a fictional reviewer discussion. I am not persuaded by the claim that the workshop caused better writing, but I do not think the programme should automatically be cancelled. We need to separate the evaluation from the service decision. A comparison of final essays is informative about the work that was submitted. It cannot tell us how much either group changed when we lack an initial sample. I would also ask whether raters knew which students attended. Expectations could influence judgements, even when a rubric is used. The next evaluation should describe the rating procedure and, where feasible, conceal attendance information from raters. That would address one possible source of bias, not every problem in the design. We would still need to understand who enrolled and who withdrew. A stronger evaluation combines several safeguards because different weaknesses require different kinds of evidence.`,focus:'审稿人新增了哪个评分风险？为什么解决它仍不能解决全部设计问题？'},
        questions:[question('reading','Which conclusion is justified by the fictional workshop comparison?',['Attendance is associated with higher ratings among submitted essays.','The workshop caused every participant to improve.','The workshop had no educational value.'],0,'现有材料支持关联，不能确认因果，也不能推出无效。'),question('reading','Why would an initial writing sample be useful?',['It would remove all need to examine withdrawal.','It would establish that raters never made errors.','It would help distinguish prior differences from subsequent change.'],2,'起点数据帮助判断组间基线与变化，不排除全部偏差。'),question('listening','What additional risk does the reviewer identify?',['Raters could be influenced by knowing workshop attendance.','Students were assigned to groups by a fair lottery.','The rubric contained no writing criteria.'],0,'审稿人提出评分者预期可能影响判断，原文未称量规无标准。'),question('listening','Why does concealing attendance from raters not settle the causal question?',['Because careful rating is never useful.','Because self-selection and withdrawal still need examination.','Because initial writing samples cannot be collected.'],1,'盲化解决特定评分偏差，不能同时解决选择与流失。')],
        production:{writing:'写 280–350 词的批判性评述：概括发现，分析两项设计限制，提出对应改进，并保留对项目实践价值的审慎判断。',speaking:'用 3 分钟向项目负责人解释为何建议继续小规模支持同时改善评价；回应“你是在说项目没用吗？”',model:'参考片段：The higher ratings are consistent with a beneficial workshop effect, but voluntary attendance and missing baseline writing leave other explanations open. Blinded rating could reduce expectation bias; it would not resolve self-selection. Continuing limited provision may be reasonable as a service decision while stronger evidence is collected.',rubric:['观察结果、机制和因果判断分开表述','每项批评对应具体可行的证据或设计改进','回应反对意见时保持准确范围，不把未证实改成无效']},
        review:{prompt:'从记忆写出两个导致组间差异的替代解释，并为其中一个设计有针对性的核查。',answer:'可用原有写作能力或动机导致自选、评分者期待、提交样本遗漏退出者。核查例：收集起点写作并比较变化；评分者不见参加信息只能处理评分预期。'}}),
      lesson({id:'c1-calibrating-claims',title:'谨慎而有立场：校准结论强度',skill:'学术写作 · 限定语言',minutes:45,
        goals:['把不确定性定位到原因、范围或测量，而非机械堆叠 may','区分没有发现效应与已经证明没有效应'],
        explanation:[point('限定的是哪一部分','The estimate was imprecise 限定精度；in this sample 限定对象；may reflect 限定解释。不同限定语解决不同问题。不要把所有结论都写成含糊的可能。'),point('保留能够确定的部分','可以明确陈述记录了多少次、采用了什么设计，然后谨慎解释这些事实。非显著结果并不自动证明等效；必须了解设计精度、比较目标及不确定范围。')],
        vocabulary:[vocab('inconclusive','无法给出明确判断的','The comparison was inconclusive.'),vocab('compatible with','与某种解释相容；不等于证实','The estimate is compatible with several explanations.'),vocab('scope','适用范围','The scope of the claim should match the sample.')],
        reading:{title:'What a small trial can say — fictional evaluation',text:`A fictional library tested two reminder messages over a short period. One message explained the booking policy; the other also described how to cancel a reservation. The observed cancellation rates were similar. Because relatively few bookings occurred, the evaluation could not distinguish a small difference from ordinary variation with much precision. The report nevertheless announced that additional instructions made no difference.
That conclusion goes beyond the information described. A cautious alternative is not merely to insert perhaps into the original sentence. The writer needs to identify what remains uncertain. The trial produced no clear evidence of a difference during this period, but it did not establish that the two messages were equivalent under all relevant conditions. A longer evaluation or a more informative design could narrow the uncertainty.
Some aspects of the report can be stated firmly. Both messages were delivered through the same system, and the trial lasted two weeks. These are descriptions of procedure, not claims about effectiveness. The distinction matters because excessive hedging can obscure facts just as excessive certainty can exaggerate interpretations.
A useful conclusion would specify the setting, acknowledge the imprecision, and explain what decision follows. The library might retain the clearer message because it helps users understand cancellation, while avoiding a claim that improved wording has been shown to reduce unused reservations. That practical preference and the empirical claim require different forms of support.`,support:'找出程序事实、观察结果和超范围结论。把不确定性写清楚，比单纯增加 maybe 更有用。'},
        listening:{title:'A discussion about the conclusion',text:`In this fictional editorial meeting, I would keep the sentence saying that cancellation rates were similar in the two-week trial. It tells readers what happened. I would revise the next sentence, which treats similarity as proof that wording never matters. The sample was small, and the report does not show that the evaluation could reliably detect a difference important to the library. That is a question about precision and design. It is not a reason to assume that the alternative message must be superior. We should avoid both errors. If staff prefer the additional instructions because they answer a frequent user question, say that this is the reason. Then propose a future evaluation with a defined outcome and an explicit account of what size of difference would affect the decision. The aim is a conclusion that is useful without pretending to be more certain than the evidence permits.`,focus:'编辑要求避免的两种相反错误是什么？记录实践选择与效果证据的差别。'},
        questions:[question('reading','What is wrong with concluding that the messages are equivalent?',['Procedure can never be described with certainty.','The imprecise comparison does not establish equivalence.','Any similar observed rates prove a large effect.'],1,'相近点估计不等于已可靠排除有实践意义的差异。'),question('reading','Which statement can be made firmly from the described procedure?',['The trial lasted two weeks.','Wording never affects cancellation.','The clearer message reduces unused bookings.'],0,'两周是已提供的程序事实；另两项超出证据。'),question('listening','Which pair of errors does the editor warn against?',['Reporting procedure and defining outcomes.','Preferring clarity and seeking better data.','Assuming no effect and assuming the alternative must be better.'],2,'不确定性既不能被当成无效证明，也不能当成相反方案有效的证据。'),question('listening','What should the next evaluation define in advance?',['A conclusion that guarantees adoption.','An outcome and a difference meaningful for the decision.','A rule that clearer messages cannot fail.'],1,'要把结果指标和具有实践意义的差异明确化。')],
        production:{writing:'写 250–320 词的结论与建议，包含一条确定的程序事实、一条限定的结果解释和一条有理由的实践选择。',speaking:'用 2 分钟回应“没有显著差异就表示一样好”的说法；用日常语言解释精度限制。',model:'参考片段：The messages produced similar cancellation rates during the two-week trial, but the limited data do not establish equivalence. Retaining the fuller instructions could be justified by their explanatory value. Whether they reduce unused bookings remains an empirical question for a more informative evaluation.',rubric:['限定语明确对应精度、范围或解释，不机械堆叠','没有把未发现差异写成等效或把不确定写成替代方案有效','建议说明实践理由，并与效果推断分开']},
        review:{prompt:'不看原文，把 The new message does not work 改为一条符合小样本不确定性的结论，再给一条独立的实践建议。',answer:'例：The short trial did not provide clear evidence of a difference; it did not rule out a meaningful effect. The library could retain the fuller explanation for clarity while evaluating its effects separately.'}}),
      lesson({id:'c1-synthesising-sources',title:'跨来源综合：围绕问题组织证据',skill:'综合阅读 · 论证组织',minutes:55,
        goals:['比较来源的对象、指标和范围，解释表面冲突','围绕问题形成综合判断，不把来源摘要简单串联'],
        explanation:[point('先建立比较框架','把每个来源的对象、方法、指标、结果和限制放进同一张表。只有比较相近的问题时，结果才直接构成冲突。不同指标可能描述同一过程的不同环节。'),point('让段落围绕主张','一个段落提出一个可支持的综合判断，再把来源放在相应位置。保留不一致的信息；不要为了整齐强行达成共识。虚构练习来源不可作为真实论文引用。')],
        vocabulary:[vocab('convergence','不同证据趋于一致','Convergence across methods strengthens a qualified interpretation.'),vocab('divergence','分歧；结果不同','The divergence may reflect different outcomes.'),vocab('complementary','互补的','The interviews provide complementary evidence.')],
        reading:{title:'Two views of recorded lectures — fictional sources',text:`The following sources are fictional teaching materials. Source A describes an undergraduate survey in which many respondents said recorded lectures helped them manage conflicting schedules. The survey focused on perceived access and convenience. It did not test learning, and students who never opened the course website were unlikely to encounter the invitation to respond.
Source B follows a small postgraduate seminar in which the tutor compared contributions before and after recordings became available. Contributions became more detailed, but the tutor also introduced written preparation questions during the same period. The observations therefore cannot isolate the contribution of recordings. They concern seminar participation rather than the scheduling problems measured in Source A.
An argument that the two sources prove recordings improve learning would overlook both the different outcomes and the limitations of each design. Yet describing the sources as contradictory would also be misleading. They may address complementary parts of a learning process: obtaining access to material and preparing to discuss it.
A defensible synthesis would identify that possible connection as a hypothesis. Recordings may support preparation when students can access them and have guidance on how to use them. Evaluating this account would require evidence about actual use, preparation and subsequent performance, including experiences of students missing from the survey. The writer's contribution lies in explaining the relationship between the sources and what remains unresolved, rather than giving each source a separate paragraph and ending with a general claim that technology is beneficial.`,support:'按 access、preparation、performance 分栏。判断材料是在回答同一问题，还是互补的不同问题。'},
        listening:{title:'A seminar participant challenges the synthesis',text:`This is a fictional seminar exchange. Your proposed connection between access and preparation is reasonable, but I would describe it as something to investigate. Source A tells us about convenience as reported by respondents. It does not show how the recordings were used. Source B provides richer observations of discussion, although the preparation questions changed at the same time. Before combining these results, I would ask what evidence would connect the two processes. For example, could students explain which parts they revisited and how that affected a specific contribution? Such accounts would not establish a causal effect by themselves, but they could help refine the mechanism. I would also include students who found the recordings unhelpful. Their experience might reveal conditions under which the proposed connection breaks down. A synthesis becomes stronger when it makes room for that possibility rather than treating every source as a vote for the same conclusion.`,focus:'说话者建议补充哪种连接证据？为什么还要纳入认为录播没帮助的人？'},
        questions:[question('reading','Why are the two fictional sources not necessarily contradictory?',['They measure different, potentially complementary processes.','They both directly measure examination gains.','They use identical samples and designs.'],0,'A关注感知可及性，B关注研讨参与；不是同一指标的直接冲突。'),question('reading','Which synthesis best respects the evidence?',['Recorded lectures have been proven to raise achievement.','Recordings may connect access and preparation, but that account needs testing.','Neither source contains information worth using.'],1,'综合可以提出有根据的机制假设，同时明确未验证。'),question('listening','What is the suggested role of students’ accounts of revisiting material?',['To replace all other evidence permanently.','To prove causality without a comparison.','To help refine a possible mechanism.'],2,'访谈可澄清使用过程，但本身不直接识别因果效应。'),question('listening','Why include students who found recordings unhelpful?',['To identify conditions where the proposed relationship may fail.','To guarantee a favourable overall conclusion.','To remove the need for preparation questions.'],0,'反例有助界定机制适用条件，而不是应被排除的噪声。')],
        production:{writing:'写 300–400 词的综合段落组，围绕一个主张整合 A、B 和听力建议；说明互补性、限制和下一步证据。标明三者均为虚构课堂材料。',speaking:'用 3 分钟解释你的综合主张，随后回应“两个来源都支持，所以已经证实”的质疑。',model:'参考片段：The fictional sources address complementary aspects of participation: access to material and preparation for discussion. Together they motivate, rather than establish, a proposed connection between recorded access and richer contributions. Differences in outcomes and simultaneous instructional changes prevent a direct causal conclusion. Accounts of both successful and unsuccessful use could help specify the conditions to test.',rubric:['以问题和论点组织来源，而非逐个摘要后跳到大结论','准确保留各来源指标、限制及未解决的关系','提出能检验综合解释的新证据，并纳入反例']},
        review:{prompt:'画出两个来源各自测量什么，再写一句综合主张和一句尚缺的证据。',answer:'A是回复者报告的便利/可及性，B是同时改变准备问题后的研讨贡献。可提出录播帮助准备的假设，但要补实际使用与准备、表现之间的证据。'}}),
      lesson({id:'c1-paraphrase-attribution',title:'准确改写：保留意义、范围与来源',skill:'学术诚信 · 改写',minutes:50,
        goals:['改变表达组织而不扭曲原文限定和对象','区分引用来源、作者主张与自己的推论'],
        explanation:[point('先理解，再离开原文重写','先记录核心关系和限制，再用自己的结构表达，最后对照原文检查遗漏和新增。只换几个同义词常常保留原句结构，也容易改变术语含义。'),point('归属与改写是两条要求','用了自己的语言仍需注明思想来源。自己推导的建议也要与来源实际说过的话分开。直接保留特殊措辞时按引用规范处理；本课虚构材料只用于练习，不可虚构为真实出版物。')],
        vocabulary:[vocab('attribution','观点或材料的来源归属','Attribution remains necessary after paraphrasing.'),vocab('distort','歪曲；改变原意','Removing the condition would distort the claim.'),vocab('provisional','暂定的；有待进一步验证','The explanation remains provisional.')],
        reading:{title:'A faithful paraphrase has boundaries',text:`The following passage is an original fictional source for practice, labelled Teaching Note A: In the first month of the pilot, several interviewed students described the planning worksheet as useful when they had already chosen a project question. Their comments do not establish whether the worksheet helps students formulate a question in the first place.
A poor paraphrase might claim that the pilot proved planning worksheets help students develop research questions. It changes interviewed students into all students, turns reported usefulness into demonstrated effectiveness, and removes the condition that a question had already been chosen. The wording may look different, but the meaning has become less faithful.
A better paraphrase would retain the population, the nature of the evidence and the condition. It might explain that some interviewees found the worksheet helpful for planning after selecting a question, while its value for question development remained untested. A reference to Teaching Note A would still be needed in the practice response because the idea came from that source.
The writer can then add an original proposal, such as testing a separate question-development activity. However, that proposal should be signalled as the writer's recommendation, not attributed to the note. Effective source use therefore involves more than avoiding identical wording. It requires accurate boundaries between the source's observation, its limitations, and the new argument the writer builds around them.`,support:'核对四项：谁、何时、何种证据、什么条件。改写不应扩大其中任一项。'},
        listening:{title:'Feedback on a draft literature paragraph',text:`This is fictional feedback on an academic draft. You have cited the teaching note, which is helpful, but the citation does not repair the change in meaning. Your sentence says the worksheet enables students to formulate research questions. The note concerns students who already had a question. Please preserve that sequence. I would also avoid saying that the interviews proved effectiveness. They provide accounts of perceived usefulness, which are relevant but different. After a faithful paraphrase, you can make your own proposal. For instance, you might suggest comparing activities for choosing a question with activities for planning an existing project. Introduce that idea as your recommendation. Do not write that the source recommends it unless the source actually does. When revising, set the original aside briefly, write the relationship in your own structure, and then check the details against the source. Citation, independent wording and accurate meaning all matter.`,focus:'为什么已经有引用仍需重写？记录反馈中两处被改变的意思。'},
        questions:[question('reading','Which condition must a faithful paraphrase preserve?',['The worksheet had already been proved effective for all students.','The interviewees described use after choosing a project question.','Every participant had completed a dissertation.'],1,'原文条件是已经选题；不能改成帮助产生研究问题。'),question('reading','Why must the practice response still refer to Teaching Note A?',['The underlying idea remains attributable to that source.','Only identical words ever need attribution.','A reference converts a fictional note into a real publication.'],0,'自己的措辞不消除思想来源；虚构教学来源仍不能冒充真实文献。'),question('listening','What does the tutor distinguish from demonstrated effectiveness?',['Reported perceptions of usefulness.','The number of words in a citation.','An independently verified causal effect.'],0,'访谈是感知有用性的报告，不等于已经证明效果。'),question('listening','How should the new comparison of activities be presented?',['As a finding the source already established.','As a direct quotation from the note.','As the student writer’s recommendation.'],2,'这是写作者新提出的建议，需与来源主张分开。')],
        production:{writing:'写 250–320 词：准确改写 Teaching Note A，分析一种失真改写，再提出自己的后续评价建议。只用教学标签归属，不编造作者、年份或 DOI。',speaking:'用 2–3 分钟解释为何“有引用”并不能保证改写准确；给出条件改变前后的例子。',model:'参考片段：Teaching Note A, a fictional classroom source, reports that some interviewees valued the worksheet after selecting a project question. It leaves its usefulness for developing that question unresolved. I therefore recommend examining question-development support separately. This recommendation extends the discussion; it is not a conclusion reported by the note.',rubric:['保留对象、条件与证据类型，没有扩大成因果事实','使用自己的组织和措辞，同时明确观点来源','自己的建议与来源结论分开，未编造真实引用信息']},
        review:{prompt:'列出失真改写改变的三处意思，再凭记忆准确改写原始发现。',answer:'变化包括部分受访者→所有人、感知有用→效果证明、已经选题→帮助选题。例：Some interviewees valued the worksheet after selecting a question; its role in question development was not established.'}}),
      lesson({id:'c1-methods-limitations',title:'研究方法与局限：从标签走向解释',skill:'方法阅读 · 研究表达',minutes:55,
        goals:['解释操作化与测量误差如何影响结论','针对一个局限说明影响方向或不确定性，并提出可行改进'],
        explanation:[point('方法不是术语清单','看到 survey、interview、experiment 等词后，继续问对象如何进入样本、概念如何测量、数据缺失在哪里。称为 mixed methods 不自动保证两种证据被有效整合。'),point('把局限写成推理链','局限→为什么影响解释→能支持的较窄结论→如何改善。避免只写 small sample 等标签，也不要声称扩大样本能修复概念测量错误。')],
        vocabulary:[vocab('construct','要研究的抽象概念','Confidence is a construct, not a directly observed count.'),vocab('indicator','用于表示概念的可观察指标','Completion time was used as one indicator.'),vocab('transferability','发现是否及如何适用于另一情境','Readers need context to judge transferability.')],
        reading:{title:'Measuring confidence at a help desk — fictional design',text:`A fictional research team wanted to understand whether a campus help desk increased students' confidence in managing administrative tasks. The team used the time taken to complete an online form as its main indicator. Faster completion was interpreted as greater confidence. Interviews with a few users were added to the report, which described the project as a mixed-methods evaluation.
The indicator raises a conceptual problem. A student may complete the form quickly because the interface is familiar, because someone provides the answers, or because the student overlooks a difficult section. Another student may work slowly while checking the instructions carefully and still feel confident. Increasing the number of timed submissions would make the estimate of completion time more precise, but would not by itself establish that time measures confidence.
The interviews could help clarify how students understood the task and why they worked at different speeds. To perform that role, however, the analysis would need to connect particular accounts with the proposed interpretation. Merely placing interview quotations after a table would not demonstrate integration.
A revised evaluation might define confidence more explicitly, use several relevant indicators, and examine discrepancies between them. It should also describe the support available at the desk and the tasks students faced. Such contextual information allows readers to judge whether the findings might apply elsewhere. The purpose is not to eliminate every limitation before learning anything, but to make the meaning and boundaries of the evidence clear.`,support:'追问 faster=more confident 这一步是否成立。解释样本数量与概念有效性分别能解决什么。'},
        listening:{title:'A methods consultation',text:`This consultation concerns a fictional project. Before adding more participants, I would revisit your definition of confidence. You currently treat speed as if it were the construct itself. Could students explain what they felt able to do without assistance? Could you observe whether they identified and resolved an unfamiliar problem? Neither measure would be perfect, and you should avoid combining them into a score without explaining the rationale. The useful information may lie in the disagreement. A student who reports confidence but repeatedly seeks help presents a different question from one who works independently but remains anxious about mistakes. Interviews could investigate those patterns. I would select contrasting cases deliberately rather than quote only the most positive comments. Finally, describe the task and the kind of help provided, because another campus may offer a very different service under the same name. Context is part of the evidence readers need for a transfer judgement.`,focus:'顾问为什么关注指标间不一致？他建议如何选择访谈案例？'},
        questions:[question('reading','Why would a larger timed sample not resolve the central problem?',['A larger sample always makes measurements less precise.','Completion time can never be observed.','Greater precision would not establish that speed represents confidence.'],2,'核心是指标与构念关系；增大样本并不能自动修复测量解释。'),question('reading','What would meaningful integration of interviews require?',['Connecting accounts with the interpretation of specific patterns.','Placing positive quotations after any table.','Avoiding discussion of disagreements.'],0,'整合需解释资料如何回应同一问题，不是简单并列。'),question('listening','Why might disagreement between indicators be informative?',['It shows that all participants answered dishonestly.','It can reveal different experiences requiring investigation.','It proves that confidence cannot be studied.'],1,'指标冲突可能揭示不同类型经验，需进一步解释。'),question('listening','Which interview selection strategy does the consultant suggest?',['Selecting only the fastest users.','Selecting only favourable comments.','Deliberately examining contrasting cases.'],2,'对照性案例有助解释指标一致与不一致的情况。')],
        production:{writing:'写 300–400 词的方法修改备忘录，定义 confidence，提出两个互补指标，说明不一致时如何追问，并保留一个实际限制。',speaking:'用 3 分钟说明为什么“更多样本”不是唯一改进；回应“我们没有资源增加全部指标”的提问并提出优先级。',model:'参考片段：I would first clarify confidence as perceived ability to manage an unfamiliar administrative task. A self-report and an observed problem-solving task could provide complementary evidence, but their combination requires justification. Contrasting cases should guide interviews. With limited resources, improving the interpretation of existing measures takes priority over expanding an inadequately defined score.',rubric:['定义与指标有可解释联系，没有把指标直接当构念','改进对应具体问题，并说明指标冲突如何处理','建议考虑资源与情境，局限解释具体而非仅列标签']},
        review:{prompt:'用英语说明 construct 与 indicator 的区别，再指出扩大样本能改善什么、不能自动改善什么。',answer:'Construct 是抽象概念，indicator 是可观察代表。更大样本可能提高某个估计的精度，但不能自动证明 completion time 有效代表 confidence。'}}),
      lesson({id:'c1-seminar-proposal',title:'研究生研讨：提出方案、回应质疑与修订',skill:'互动表达 · 综合论证',minutes:60,
        goals:['在讨论中准确复述质疑，再有条件地回应','综合证据、可行性和公平性提出可修订的方案'],
        explanation:[point('先确认异议针对哪一层','用 If I understand your concern... 复述问题，再区分对目标、证据、方法还是实施的质疑。承认有效异议后调整主张，比机械坚持原案更能展示论证能力。'),point('建议需要决策条件','说明优先目标、方案、代价、评估指标和何时修改或停止。不要把“再研究”当作避免决策的万能句，也不要用一个总分掩盖不同群体的差异。')],
        vocabulary:[vocab('trade-off','无法同时最大化不同目标时的取舍','The proposal makes the trade-off explicit.'),vocab('feasibility','在现实条件下实施的可行性','Staff time affects feasibility.'),vocab('revision criterion','触发修改方案的判断条件','The team agreed on a revision criterion.')],
        reading:{title:'An academic writing clinic — fictional proposal',text:`A fictional graduate school is considering a writing clinic staffed by trained postgraduate volunteers. The proposal promises more frequent feedback without increasing the number of professional tutors. Supporters argue that peer discussion can make expectations clearer and allow writers to test whether an argument is understandable. Critics worry that volunteers may be asked to provide expertise they do not possess.
The debate becomes more productive when these concerns are separated. A clinic can help a writer identify an unclear claim without guaranteeing the accuracy of specialist content. It can offer questions about organisation without rewriting an assignment. The proposal should therefore define the service boundary and explain when volunteers refer a writer to a qualified tutor or supervisor.
Feasibility also depends on training, scheduling and supervision. Counting appointments alone would conceal how much preparation and follow-up each session requires. Fair access cannot be assumed if all appointments occur during hours when part-time students are at work. These issues do not necessarily defeat the proposal, but they change what a responsible pilot should include.
A revised plan might offer a limited range of feedback, reserve supervision time, and provide some appointments outside standard daytime hours. Evaluation should examine the usefulness and limits of feedback, volunteer workload and access across student groups. The pilot should have explicit revision criteria. If volunteers repeatedly receive requests beyond their competence, the service may need a narrower remit or stronger referral arrangements rather than simply a larger number of appointments.`,support:'把争议分为服务边界、资源与公平三类。看作者如何把有效质疑转成方案条件。'},
        listening:{title:'Responding to a committee challenge',text:`This is an invented committee discussion. I support a small pilot, but I would revise the claim that volunteer appointments can simply substitute for professional tutoring. If I understand the staffing concern, the issue is not only the number of appointments; it is the expertise and supervision each appointment requires. We can limit the initial service to discussing argument structure and reader understanding. Questions about specialist accuracy should be referred elsewhere. I also accept the concern about part-time students. Offering one evening session is a start, but we should ask whether it actually reaches those students rather than assuming that it does. My recommendation is conditional: run a limited pilot with protected supervision time and review the scope after the first cycle. If referral requests exceed what staff can manage, we should narrow the service before expanding it. This would preserve the goal of accessible feedback while responding to the most serious implementation risks.`,focus:'说话者在哪些方面接受质疑？方案的扩展受什么条件约束？'},
        questions:[question('reading','Which service boundary does the proposal support?',['Volunteers may discuss clarity without guaranteeing specialist accuracy.','Volunteers should certify all disciplinary claims.','Volunteers should rewrite assessed assignments.'],0,'服务可讨论论证与可理解度，不能承担不具备的专家认证职责。'),question('reading','Why are appointment totals insufficient for evaluation?',['Appointments have no relationship to service use.','They do not capture preparation, supervision or unequal access.','They already include every relevant cost.'],1,'计数遗漏时间负担与不同学生群体能否使用。'),question('listening','What does the speaker reject about the original staffing claim?',['That a limited pilot could be useful.','That part-time students may face barriers.','That volunteer sessions simply substitute for professional tutoring.'],2,'说话者支持试点，但拒绝简单替代专家辅导的假设。'),question('listening','When would the speaker narrow the service before expansion?',['If referral demands exceed manageable staff capacity.','Whenever a volunteer asks any question.','As soon as an evening session is offered.'],0,'修改条件具体对应转介需求与可承担资源。')],
        production:{writing:'写 350–450 词的委员会建议书，整合材料提出有条件的试点方案；回应两项异议，说明目标、范围、评价指标及修改条件。',speaking:'做 3–4 分钟提案，并实际口头回应两问：为什么不立即扩大？怎样确认兼职学生获益？记录你根据问题作出的修订。',model:'参考结构：I recommend a limited writing clinic rather than treating volunteer provision as interchangeable with specialist tutoring. The pilot should focus on argument clarity, protect supervision time and establish referral boundaries. Evaluation must consider workload and access alongside appointment counts. Expansion should depend on evidence that the scope is manageable and that intended users can attend; repeated unmet referral needs would justify revision before growth.',rubric:['提案整合目标、证据与实施条件，而非仅表态支持或反对','准确复述并回应两项异议，有实质修订或理由','书面组织清楚，口述重点可跟随，建议包含可检查的修改条件']},
        review:{prompt:'凭记忆口述一个有条件的试点建议：包含服务边界、一个公平指标和一个修订条件。',answer:'例如只反馈论证清晰度，专门内容转介；检查兼职学生实际预约与缺席原因；若转介需求超过辅导能力则先缩小范围再扩展。'}})
    ],
    assessment: assessment('c1', {
      reading:{title:'Should a graduate school centralise its reading groups? — fictional evaluation',text:`The following report and its findings are fictional materials written for this assessment. A graduate school piloted centrally organised reading groups to replace several informal departmental groups. The central scheme offered a published timetable, a common registration page and discussion prompts prepared by a coordinator. Its stated goals were to make participation easier and to encourage students to encounter perspectives beyond their own discipline.
During the first term, registrations increased relative to the combined lists available from the previous year. The coordinator interpreted this as evidence that centralisation had widened participation. However, the older lists were incomplete: some informal groups had recorded attendance without maintaining a registration list. The new page also allowed students to register for several groups. Without identifying duplicate registrations and clarifying the earlier counting procedures, the figures do not provide a straightforward comparison of individual participants.
Interviewed students praised the predictable timetable and the chance to meet unfamiliar peers. Some also said that common prompts were too general to support detailed discussion of specialist arguments. These comments suggest a tension between broad accessibility and disciplinary depth, but the report does not establish that the two goals are incompatible. Interviewees had volunteered after attending at least one meeting. Students who registered but never attended, and those who never registered, were not represented.
The report recommends replacing all informal groups with the central scheme. That recommendation assumes that the benefits described by attendees apply to the wider graduate population. It also treats incomplete administrative counts as though they measured the same outcome across both periods. A more defensible response would preserve useful features while investigating the uncertainties. Shared scheduling might coexist with locally selected texts and discipline-specific facilitation. Such a hybrid arrangement would itself require evaluation; it should not be presented as an already proven solution.
Before expanding the scheme, the school could define participation more carefully, distinguish registration from attendance and sustained involvement, and examine barriers among non-attendees. It could also compare the kinds of discussion supported by different formats. Evaluation would need to include coordination time and facilitator workload, since an apparently efficient central page might depend on substantial preparation elsewhere. The key decision is not whether centralisation is good or bad in the abstract. It is which functions benefit from coordination, which need local adaptation, and what evidence would justify changing that balance. A pilot with explicit review conditions could support that decision without treating one term of incomplete evidence as a final verdict.`},
      listening:{title:'A committee member responds to the report',text:`This is a fictional committee response. I would not support replacing every departmental group on the basis of the current report. That does not mean we should abandon the shared timetable. Students have identified a practical benefit, and we should take that seriously. My concern is the movement from a useful feature to a universal organisational prescription.
The registration figures need reconstruction before we use them to claim wider participation. Even after removing duplicates, we would still need to understand who attended regularly and who could not attend. I would ask a small team to contact both non-attendees and students outside the registration system. The invitations should make clear that criticism will not affect access to future groups.
On discussion quality, I suggest testing shared scheduling with locally chosen questions in a limited number of groups. Facilitators should record preparation time as well as attendance, and participants could describe a specific discussion that helped them understand or challenge an argument. Such accounts would complement observation; they would not replace it or prove that one format caused better thinking.
Finally, we should agree now on the conditions for revising the arrangement. If coordination creates an unsustainable workload, or if some students consistently find the sessions inaccessible, those findings should trigger changes before expansion. A successful pilot need not produce one identical model for every department. It may show which elements can be shared and where flexibility is necessary.`},
      questions:[question('reading','What prevents a straightforward comparison of participation across the two periods?',['Earlier records were complete and used identical definitions.','Incomplete earlier lists and potentially duplicated new registrations.','The absence of any new registration page.'],1,'记录方式不同且可能重复，不能直接把登记数比较当成参与人数变化。'),question('reading','How should the suggested hybrid arrangement be interpreted?',['As a proven solution requiring no further evaluation.','As evidence that accessibility and depth cannot coexist.','As a plausible option that still needs evaluation.'],2,'原文明确说混合方案仍需检验，而非已经证实。'),question('reading','Which limitation most directly affects claims about barriers to participation?',['Only volunteer interviewees who attended were included.','The scheme published a timetable.','The coordinator prepared prompts.'],0,'未参加和未登记人群缺席，直接限制对障碍的判断。'),question('reading','What is the report’s central decision problem as reframed by the final paragraph?',['Whether all coordination is harmful.','Which functions should be shared or adapted, under what evidence.','How to maximise registrations regardless of attendance.'],1,'问题被重构为功能、适应性和证据条件，而非抽象二选一。'),question('listening','What distinction underlies the committee member’s initial response?',['A useful shared feature does not justify a universal replacement policy.','A useful timetable proves every group should be identical.','Any limitation requires abandoning the whole scheme.'],0,'说话者承认共享时间表价值，同时限制组织层面的泛化。'),question('listening','Why should invitations to non-attendees emphasise that criticism will not affect future access?',['To guarantee that every response is favourable.','To replace the need to contact unregistered students.','To reduce concern about consequences of negative feedback.'],2,'这样有助降低表达负面经验的顾虑，但不能保证无偏差。'),question('listening','What role would participants’ accounts of specific discussions play?',['They would alone prove a causal improvement in thinking.','They would complement observation of discussion processes.','They would eliminate the need to record workload.'],1,'具体经验提供互补证据，不能独立证明因果或取代其他指标。'),question('listening','Which outcome is explicitly acceptable to the speaker?',['One identical permanent model for every department regardless of evidence.','Expansion even when access barriers persist.','A differentiated model combining shared elements with flexibility.'],2,'说话者允许试点产生分化方案，并要求扩展前处理工作量和可及性。')],
      writing:'写 450–550 词的评估备忘录，向研究生院提出有条件的建议。综合阅读和讲座，分析至少两项证据限制，区分观察与推论，设计可行的评价与修订条件。用“虚构报告／委员会回应”标注材料，不编造文献。',
      speaking:'做 4 分钟简报，然后回答：“登记数增加为什么还不够？”及“如果部门想要不同方案，你如何决定？”保存实际口述稿或包含回应与修订的反思记录。',
      rubric:['准确综合两个来源，保留对象、指标和因果范围；没有把假设写成事实','提出清楚的主张、反方回应、可行评价和具体修订条件；组织连贯且来源归属明确','口头回应能澄清问题并调整论证，语言较准确、措辞合适；对流利度与发音的自评有具体例子'],
      model:'参考论证框架：The fictional report identifies useful coordination features but does not justify replacing all departmental groups. Registration counts are not comparable measures of sustained participation, and attendee interviews omit important experiences. The committee response supports a limited test of shared scheduling with local adaptation. I recommend preserving the timetable while reconstructing participation measures, examining barriers among non-attendees and observing discussion processes. Participant accounts should complement observation, and facilitator preparation time must be recorded. Expansion should depend on workable staffing and evidence that intended users can participate; persistent barriers or unsustainable workload should trigger revision. This is a conditional proposal for testing, not a claim that a hybrid model has already been shown to improve learning. 请检查自己的文本是否真正展开理由、回应反方并给出操作步骤；一段参考摘要不是整篇 450–550 词的标准答案。'
    })
  };
  window.PATHWAY_ADVANCED = [b1, b2, c1];
})();
